insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-caesar-0', 'caesar', 'mission', 'Signal Intercept', 'decoding', 1, array['transmission','boardroom','any']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 98.7 MHz ]  YHKPHUA\n[ 101.3 MHz ]  IUDJYDUB\n[ 91.1 MHz ]  XJHKVNN","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 98.7 MHz\nEncryption key: 7\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["RADIANT"]}]'::jsonb, false, 3, 200, 'The answer has 7 letters and starts with R.', '98.7 MHz carries YHKPHUA; shifting back by 7 gives RADIANT.', null, 25, 'published'), ('mission-caesar-1', 'caesar', 'mission', 'Signal Intercept', 'decoding', 1, array['gate','access','transmission']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 94.3 MHz ]  AEKXDEW\n[ 98.7 MHz ]  YKTZOTKR\n[ 88.4 MHz ]  VYUWIH","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 98.7 MHz\nEncryption key: 6\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["SENTINEL"]}]'::jsonb, false, 3, 200, 'The answer has 8 letters and starts with S.', '98.7 MHz carries YKTZOTKR; shifting back by 6 gives SENTINEL.', null,