insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-sequence-1', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  5, 9, 13, 17, 21, ?\nBRAVO:  2, 3, 5, 8, 13, ?\nCHARLIE:  4, 8, 16, 32, 64, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number plus 10."},"intel":{"title":"Insider tip","body":"The genuine pattern is BRAVO. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["31"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'BRAVO continues with 21; converted: 31.', null, 25, 'published'), ('mission-sequence-2', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  4, 8, 16, 32, 64, ?\nBRAVO:  5, 8, 11, 14, 17, ?\nCHARLIE:  4, 9, 19, 39, 79, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number multiplied by 2."},"intel":{"title":"Insider tip","body":"The genuine pattern is CHARLIE. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["318"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'CHARLIE continues with 159; converted: 318.', null, 25, 'published'), ('mission-sequence-3', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  4, 9, 19, 39, 79, ?\nBRAVO:  4, 9, 16, 25, 36, ?\nCHARLIE:  2, 4, 6, 10, 16, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number minus 1."},"intel":{"title":"Insider tip","body":"The genuine pattern is ALPHA. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["158"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'ALPHA continues with 159; converted: 158.', null, 25, 'published'), ('mission-sequence-4', 'sequence', 'mission', 'Pattern Lock', 'logic', 1, array['learning','office','glass','phase2','any']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  4, 11, 18, 25, 32, ?\nBRAVO:  4, 8, 16, 32, 64, ?\nCHARLIE:  1, 3, 7, 15, 31, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number plus 10."},"intel":{"title":"Insider tip","body":"The genuine pattern is BRAVO. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["138"]}]'::jsonb, false, 3, 200, 'Look at the difference (or ratio) between neighbouring numbers.', 'BRAVO continues with 128; converted: 138.', null, 25, 'published'), ('mission-memory-0', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"📱   🎧   🔋   ☕   📦   🍩   📎","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = X    🍩 = I    📎 = J    🖥️ = S    🔑 = W    📦 = F    🎧 = D    📱 = Q    🧾 = R    🔋 = M"},"intel":{"title":"Positions that matter","body":"Use only objects number 5, 6, 7 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["FIJ"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 5, 6, 7 were 📦 🍩 📎 → FIJ.', null, 25, 'published'), ('mission-memory-1', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"📎   🔑   🧾   ☕   🖥️   📦   🎧","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = F    🍩 = D    📎 = K    🖥️ = N    🔑 = P    📦 = Y    🎧 = X    📱 = J    🧾 = R    🔋 = T"},"intel":{"title":"Positions that matter","body":"Use only objects number 2, 4, 6 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["PFY"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 2, 4, 6 were 🔑 ☕ 📦 → PFY.', null, 25, 'published'), ('mission-memory-2', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"🔋   🍩   ☕   🔑   🧾   📦   📎","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = B    🍩 = O    📎 = X    🖥️ = U    🔑 = I    📦 = N    🎧 = G    📱 = H    🧾 = S    🔋 = L"},"intel":{"title":"Positions that matter","body":"Use only objects number 1, 3, 6 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["LBN"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 1, 3, 6 were 🔋 ☕ 📦 → LBN.', null, 25, 'published'), ('mission-memory-3', 'memory', 'mission', 'Flash Memory', 'memory', 2, array['food','healing','costa','learning']::text[], 'A security camera flashed a sequence of objects for a few seconds. Rebuild the code from it.', '{"scout":{"title":"Camera flash (disappears after 20 s!)","body":"🔑   🖥️   📱   ☕   📦   🔋   📎","reveal_seconds":20},"decoder":{"title":"Object → letter key","body":"☕ = J    🍩 = Z    📎 = R    🖥️ = D    🔑 = Y    📦 = F    🎧 = G    📱 = C    🧾 = N    🔋 = T"},"intel":{"title":"Positions that matter","body":"Use only objects number 1, 3, 4 (counting from the left)."}}'::jsonb, '[{"label":"Letter code","accept":["YCJ"]}]'::jsonb, false, 3, 200, 'Scout: say the objects out loud while they are visible.', 'Positions 1, 3, 4 were 🔑 📱 ☕ → YCJ.', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

