insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-triad-203', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"Hexadecimal F equals which decimal number?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Function key that refreshes most browser pages: F?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"HTTP status code for \"Forbidden\"?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["15"]},{"label":"Part 2 (Decoder)","accept":["5"]},{"label":"Part 3 (Intel)","accept":["403"]}]'::jsonb, false, 3, 90, 'The three numbers have 2, 1, 3 digits.', 'Hexadecimal F equals which decimal number? → 15 | Function key that refreshes most browser pages: F? → 5 | HTTP status code for "Forbidden"? → 403', null, 25, 'published'), ('battle-triad-204', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"How many bytes are in one kibibyte (KiB)?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"In most programming languages, the index of the first array element is?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"How many bits are in one byte?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["1024"]},{"label":"Part 2 (Decoder)","accept":["0"]},{"label":"Part 3 (Intel)","accept":["8"]}]'::jsonb, false, 3, 90, 'The three numbers have 4, 1, 1 digits.', 'How many bytes are in one kibibyte (KiB)? → 1024 | In most programming languages, the index of the first array element is? → 0 | How many bits are in one byte? → 8', null, 25, 'published'), ('battle-triad-205', 'triad', 'battle', 'Tech Triad', 'tech', 1, array['duel_pistol']::text[], 'Each teammate holds one tech question. Collect all three numbers and enter them in order.', '{"scout":{"title":"Code fragment 1 of 3","body":"HTTP status code for \"Forbidden\"?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"Hexadecimal F equals which decimal number?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"Hexadecimal 1A equals which decimal number?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Part 1 (Scout)","accept":["403"]},{"label":"Part 2 (Decoder)","accept":["15"]},{"label":"Part 3 (Intel)","accept":["26"]}]'::jsonb, false, 3, 90, 'The three numbers have 3, 2, 2 digits.', 'HTTP status code for "Forbidden"? → 403 | Hexadecimal F equals which decimal number? → 15 | Hexadecimal 1A equals which decimal number? → 26', null, 25, 'published'), ('battle-keypad-200', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 8, 3, 5\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"ODD digits come first (smallest to largest), then EVEN digits (largest to smallest)."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: swap the 1st and last digits before entering."}}'::jsonb, '[{"label":"Access code","accept":["8593"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 3598, after the wiring fault 8593.', null, 25, 'published'), ('battle-keypad-201', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 7, 2, 4, 3\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from SMALLEST to LARGEST digit."},"intel":{"title":"Maintenance report","body":"The panel adds 1 to the LAST digit (9 becomes 0)."}}'::jsonb, '[{"label":"Access code","accept":["2348"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 2347, after the wiring fault 2348.', null, 25, 'published'), ('battle-keypad-202', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 1, 5, 7, 4\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: swap the 1st and last digits before entering."}}'::jsonb, '[{"label":"Access code","accept":["1547"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 7541, after the wiring fault 1547.', null, 25, 'published'), ('battle-keypad-203', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_pistol']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 3, 6, 2\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from SMALLEST to LARGEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: the 2nd and 3rd digits are swapped."}}'::jsonb, '[{"label":"Access code","accept":["2639"]}]'::jsonb, false, 3, 90, 'The code has 4 digits.', 'Ordered digits 2369, after the wiring fault 2639.', null, 25, 'published'), ('battle-keypad-300', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_smg']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 3, 4\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: the 2nd and 3rd digits are swapped."}}'::jsonb, '[{"label":"Access code","accept":["934"]}]'::jsonb, false, 3, 50, 'The code has 3 digits.', 'Ordered digits 943, after the wiring fault 934.', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

