insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-keypad-301', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_smg']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 1, 5, 9\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"ODD digits come first (smallest to largest), then EVEN digits (largest to smallest)."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: swap the 1st and last digits before entering."}}'::jsonb, '[{"label":"Access code","accept":["951"]}]'::jsonb, false, 3, 50, 'The code has 3 digits.', 'Ordered digits 159, after the wiring fault 951.', null, 25, 'published'), ('battle-keypad-302', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_smg']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 3, 5, 9\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from SMALLEST to LARGEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: the 2nd and 3rd digits are swapped."}}'::jsonb, '[{"label":"Access code","accept":["395"]}]'::jsonb, false, 3, 50, 'The code has 3 digits.', 'Ordered digits 359, after the wiring fault 395.', null, 25, 'published'), ('battle-keypad-303', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_smg']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 5, 4, 7\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The panel adds 1 to the LAST digit (9 becomes 0)."}}'::jsonb, '[{"label":"Access code","accept":["755"]}]'::jsonb, false, 3, 50, 'The code has 3 digits.', 'Ordered digits 754, after the wiring fault 755.', null, 25, 'published'), ('battle-keypad-304', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_smg']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 8, 9, 3\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"Enter the code in REVERSE order."}}'::jsonb, '[{"label":"Access code","accept":["389"]}]'::jsonb, false, 3, 50, 'The code has 3 digits.', 'Ordered digits 983, after the wiring fault 389.', null, 25, 'published'), ('battle-keypad-305', 'keypad', 'battle', 'Worn Keypad', 'decoding', 1, array['duel_smg']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 2, 3, 4\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from SMALLEST to LARGEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: swap the 1st and last digits before entering."}}'::jsonb, '[{"label":"Access code","accept":["432"]}]'::jsonb, false, 3, 50, 'The code has 3 digits.', 'Ordered digits 234, after the wiring fault 432.', null, 25, 'published'), ('battle-caesar-400', 'caesar', 'battle', 'Signal Intercept', 'decoding', 2, array['duel_sniper']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 107.2 MHz ]  QXARIXW\n[ 88.4 MHz ]  TWGNYFQ\n[ 94.3 MHz ]  FXKBWBTG","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 88.4 MHz\nEncryption key: 5\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["ORBITAL"]}]'::jsonb, false, 3, 120, 'The answer has 7 letters and starts with O.', '88.4 MHz carries TWGNYFQ; shifting back by 5 gives ORBITAL.', null, 25, 'published'), ('battle-caesar-401', 'caesar', 'battle', 'Signal Intercept', 'decoding', 2, array['duel_sniper']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 98.7 MHz ]  OAYBMEE\n[ 101.3 MHz ]  XCRTZVI\n[ 104.9 MHz ]  NITKWV","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 104.9 MHz\nEncryption key: 8\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["FALCON"]}]'::jsonb, false, 3, 120, 'The answer has 6 letters and starts with F.', '104.9 MHz carries NITKWV; shifting back by 8 gives FALCON.', null, 25, 'published'), ('battle-caesar-402', 'caesar', 'battle', 'Signal Intercept', 'decoding', 2, array['duel_sniper']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 94.3 MHz ]  KPEGMIV\n[ 91.1 MHz ]  BEOVGNY\n[ 98.7 MHz ]  JSVASFL","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 94.3 MHz\nEncryption key: 4\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["GLACIER"]}]'::jsonb, false, 3, 120, 'The answer has 7 letters and starts with G.', '94.3 MHz carries KPEGMIV; shifting back by 4 gives GLACIER.', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

