insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-caesar-403', 'caesar', 'battle', 'Signal Intercept', 'decoding', 2, array['duel_sniper']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 94.3 MHz ]  DHNAGHZ\n[ 88.4 MHz ]  YDSUAWJ\n[ 107.2 MHz ]  BNWCRWNU","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 107.2 MHz\nEncryption key: 9\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["SENTINEL"]}]'::jsonb, false, 3, 120, 'The answer has 8 letters and starts with S.', '107.2 MHz carries BNWCRWNU; shifting back by 9 gives SENTINEL.', null, 25, 'published'), ('battle-grid-400', 'grid', 'battle', 'Coordinate Drop', 'observation', 2, array['duel_sniper']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | T B P K C\n2 | R H N C C\n3 | R G J U S\n4 | S L D Z A\n5 | D W E S A","mono":true},"decoder":{"title":"Marked coordinates","body":"(5, 3)  (3, 1)  (5, 4)  (1, 2)  (4, 1)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SPARK"]}]'::jsonb, false, 3, 120, 'The code is a 5-letter word ending in K.', 'Reading (column,row) gives SPARK; reading it as (row,column) gives nonsense (ERSBS).', null, 25, 'published'), ('battle-grid-401', 'grid', 'battle', 'Coordinate Drop', 'observation', 2, array['duel_sniper']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | L V D G O\n2 | Y I A E U\n3 | R D G J A\n4 | X U B R O\n5 | J M K R A","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 5)  (3, 2)  (4, 5)  (3, 5)  (4, 2)  (1, 3)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["MARKER"]}]'::jsonb, false, 3, 120, 'The code is a 6-letter word ending in R.', 'Reading (column,row) gives MARKER; reading it as (row,column) gives nonsense (UDOAUD).', null, 25, 'published'), ('battle-grid-402', 'grid', 'battle', 'Coordinate Drop', 'observation', 2, array['duel_sniper']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | C L I C T\n2 | K E K Z V\n3 | K R R P T\n4 | O S W E E\n5 | U W F H P","mono":true},"decoder":{"title":"Marked coordinates","body":"(5, 1)  (1, 4)  (3, 4)  (5, 4)  (2, 3)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["TOWER"]}]'::jsonb, false, 3, 120, 'The code is a 5-letter word ending in R.', 'Reading (column,row) gives TOWER; reading it as (row,column) gives nonsense (UCPHK).', null, 25, 'published'), ('battle-grid-403', 'grid', 'battle', 'Coordinate Drop', 'observation', 2, array['duel_sniper']::text[], 'A supply crate is marked on a letter grid. Read the drop code from the marked squares.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | D A R T B\n2 | Y T E E M\n3 | D R F I O\n4 | L C S G A\n5 | E A F P I","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 4)  (3, 1)  (2, 5)  (4, 1)  (1, 5)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["CRATE"]}]'::jsonb, false, 3, 120, 'The code is a 5-letter word ending in E.', 'Reading (column,row) gives CRATE; reading it as (row,column) gives nonsense (EDMLB).', null, 25, 'published'), ('recovery-keypad-500', 'keypad', 'recovery', 'Worn Keypad', 'decoding', 1, array['any']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 8, 9, 5\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The panel adds 1 to the LAST digit (9 becomes 0)."}}'::jsonb, '[{"label":"Access code","accept":["986"]}]'::jsonb, false, 5, 120, 'The code has 3 digits.', 'Ordered digits 985, after the wiring fault 986.', null, 25, 'published'), ('recovery-keypad-501', 'keypad', 'recovery', 'Worn Keypad', 'decoding', 1, array['any']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 5, 3\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"ODD digits come first (smallest to largest), then EVEN digits (largest to smallest)."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: the 2nd and 3rd digits are swapped."}}'::jsonb, '[{"label":"Access code","accept":["395"]}]'::jsonb, false, 5, 120, 'The code has 3 digits.', 'Ordered digits 359, after the wiring fault 395.', null, 25, 'published'), ('recovery-keypad-502', 'keypad', 'recovery', 'Worn Keypad', 'decoding', 1, array['any']::text[], 'Crack the checkpoint keypad. Enter the digits exactly as the panel expects them.', '{"scout":{"title":"Keypad photo","body":"Worn (most-pressed) keys: 9, 5, 3\nEach worn key is used exactly once."},"decoder":{"title":"Guard''s habit","body":"The code was typed from LARGEST to SMALLEST digit."},"intel":{"title":"Maintenance report","body":"The wiring is faulty: swap the 1st and last digits before entering."}}'::jsonb, '[{"label":"Access code","accept":["359"]}]'::jsonb, false, 5, 120, 'The code has 3 digits.', 'Ordered digits 953, after the wiring fault 359.', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

