insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('finale_battle-sequence-901', 'sequence', 'finale_battle', 'Pattern Lock', 'logic', 2, array['finale']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  6, 13, 20, 27, 34, ?\nBRAVO:  4, 9, 16, 25, 36, ?\nCHARLIE:  1, 3, 4, 7, 11, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number plus 10."},"intel":{"title":"Insider tip","body":"The genuine pattern is BRAVO. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["59"]}]'::jsonb, false, 3, 150, 'Look at the difference (or ratio) between neighbouring numbers.', 'BRAVO continues with 49; converted: 59.', null, 25, 'published'), ('finale_battle-sequence-902', 'sequence', 'finale_battle', 'Pattern Lock', 'logic', 2, array['finale']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  3, 7, 15, 31, 63, ?\nBRAVO:  3, 4, 7, 11, 18, ?\nCHARLIE:  3, 6, 12, 24, 48, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number minus 1."},"intel":{"title":"Insider tip","body":"The genuine pattern is ALPHA. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["126"]}]'::jsonb, false, 3, 150, 'Look at the difference (or ratio) between neighbouring numbers.', 'ALPHA continues with 127; converted: 126.', null, 25, 'published'), ('finale_battle-binary-900', 'binary', 'finale_battle', 'Badge Reader', 'tech', 2, array['finale']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag D:  ○ ○ ● ○ ○\nTag B:  ● ○ ● ○ ●\nTag G:  ○ ● ● ○ ○\nTag F:  ○ ● ● ● ●\nTag J:  ○ ○ ○ ● ●","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nJ → G → F → B → D"}}'::jsonb, '[{"label":"Badge word","accept":["CLOUD"]}]'::jsonb, false, 3, 150, 'It is a 5-letter tech word.', 'J=3=C, G=12=L, F=15=O, B=21=U, D=4=D → CLOUD.', null, 25, 'published'), ('finale_battle-binary-901', 'binary', 'finale_battle', 'Badge Reader', 'tech', 2, array['finale']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag G:  ● ○ ○ ● ●\nTag R:  ○ ○ ○ ● ●\nTag N:  ○ ● ○ ● ●\nTag K:  ○ ○ ○ ○ ●\nTag B:  ● ○ ● ○ ○","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nG → B → K → R → N"}}'::jsonb, '[{"label":"Badge word","accept":["STACK"]}]'::jsonb, false, 3, 150, 'It is a 5-letter tech word.', 'G=19=S, B=20=T, K=1=A, R=3=C, N=11=K → STACK.', null, 25, 'published'), ('finale_battle-binary-902', 'binary', 'finale_battle', 'Badge Reader', 'tech', 2, array['finale']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag R:  ○ ○ ● ○ ●\nTag H:  ● ○ ○ ● ○\nTag J:  ○ ● ● ○ ●\nTag W:  ○ ○ ● ○ ●\nTag K:  ○ ○ ● ● ●","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nJ → R → H → K → W"}}'::jsonb, '[{"label":"Badge word","accept":["MERGE"]}]'::jsonb, false, 3, 150, 'It is a 5-letter tech word.', 'J=13=M, R=5=E, H=18=R, K=7=G, W=5=E → MERGE.', null, 25, 'published'), ('final_code-grid-1000', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | D J U R L F\n2 | E Z N E B S\n3 | V V E A S R\n4 | O O I F Z E\n5 | D S N X C R\n6 | I N W B I G","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 5)  (3, 4)  (6, 3)  (3, 1)  (6, 2)  (6, 4)  (6, 5)  (1, 6)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SIRUSERI"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in I.', 'Reading (column,row) gives SIRUSERI; reading it as (row,column) gives nonsense (BAWVNBIF).', null, 25, 'published'), ('final_code-grid-1001', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | Z J Z T N O\n2 | H G W R Y M\n3 | N F B Y A F\n4 | O M B Q E X\n5 | K U L F J O\n6 | R P Q L H V","mono":true},"decoder":{"title":"Marked coordinates","body":"(3, 1)  (5, 4)  (4, 2)  (1, 4)  (1, 2)  (6, 5)  (2, 5)  (1, 6)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["ZEROHOUR"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in R.', 'Reading (column,row) gives ZEROHOUR; reading it as (row,column) gives nonsense (NFMTJHYO).', null, 25, 'published'), ('final_code-grid-1002', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | W P N F C J\n2 | V D N U A Z\n3 | G C E F A H\n4 | O P A Y R Z\n5 | U N M X Z X\n6 | J C I U H I","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 6)  (5, 6)  (3, 4)  (3, 5)  (2, 4)  (3, 6)  (1, 4)  (3, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["CHAMPION"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in N.', 'Reading (column,row) gives CHAMPION; reading it as (row,column) gives nonsense (ZXFAUHFC).', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

