insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pic-4', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🦷 + 🖌️\n\n(10 letters · starts with T)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🛏️ + 🪨\n\n(7 letters · starts with B)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🧠 + ⛈️\n\n(10 letters · starts with B)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["TOOTHBRUSH"]},{"label":"Picture 2 (Decoder)","accept":["BEDROCK"]},{"label":"Picture 3 (Intel)","accept":["BRAINSTORM"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: TO…, BE…, BR…', 'TOOTHBRUSH: tooth + brush | BEDROCK: bed + rock | BRAINSTORM: brain + storm', null, 25, 'published'), ('recovery-pic-0', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"☀️ + 🌻\n\n(9 letters · starts with S)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🔑 + 🎹\n\n(8 letters · starts with K)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"☁️ + 🖥️\n\n(2 words: 5 + 9 · starts with C)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["SUNFLOWER"]},{"label":"Picture 2 (Decoder)","accept":["KEYBOARD"]},{"label":"Picture 3 (Intel)","accept":["CLOUDCOMPUTING","CLOUDCOMPUTER"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words. Answers start with: SU…, KE…, CL…', 'SUNFLOWER: sun + flower | KEYBOARD: key + board | CLOUD COMPUTING: cloud + computer → cloud computing', null, 25, 'published'), ('recovery-pic-1', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🐝 + 🍃\n\n(7 letters · starts with B)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🌊 + 🐎\n\n(8 letters · starts with S)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🕷️ + 🕸️ + 🌐\n\n(3 words: 5 + 4 + 3 · starts with W)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["BAYLEAF","BEELEAF"]},{"label":"Picture 2 (Decoder)","accept":["SEAHORSE"]},{"label":"Picture 3 (Intel)","accept":["WORLDWIDEWEB","WEBSITE","WWW"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words. Answers start with: BA…, SE…, WO…', 'BAYLEAF: bee (bay) + leaf | SEAHORSE: sea + horse | WORLD WIDE WEB: the world-wide web', null, 25, 'published'), ('mission-riddle-0', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have keys but open no locks. You type on me every day.\n\n(8 letters · starts with K)","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"What has to be broken before you can use it? (Breakfast!)\n\n(3 letters · starts with E)","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"I am tall when I am new and short when I am old. I give light.\n\n(6 letters · starts with C)","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["KEYBOARD"]},{"label":"Riddle 2 (Decoder)","accept":["EGG","ANEGG"]},{"label":"Riddle 3 (Intel)","accept":["CANDLE","ACANDLE"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns. Answers start with: KE…, EG…, CA…', 'KEYBOARD: a keyboard | EGG: an egg | CANDLE: a candle', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

