insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-fruit-0', 'fruit', 'mission', 'Fruit Slash', 'game', 1, array['any','food','healing','social','costa','sports','market']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍊","d":6},{"f":"🥝","d":8},{"f":"🍒","d":5},{"f":"🍓","d":4},{"f":"🍉","d":2},{"f":"🥭","d":7}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍒   🥝   🍓   🍉\n(Cherry, Kiwi, Strawberry, Watermelon)","big":true},"decoder":{"title":"Scramble rule","body":"Add 1 to every digit (9 becomes 0)."}}'::jsonb, '[{"label":"4-digit vault code","accept":["6953"]}]'::jsonb, false, 3, 200, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍒=5 🥝=8 🍓=4 🍉=2 → +1 to each digit → 6953', null, 25, 'published'), ('mission-fruit-1', 'fruit', 'mission', 'Fruit Slash', 'game', 1, array['any','food','healing','social','costa','sports','market']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍇","d":5},{"f":"🍍","d":2},{"f":"🍎","d":8},{"f":"🥝","d":3},{"f":"🍓","d":4},{"f":"🍌","d":1}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🥝   🍍   🍇   🍌\n(Kiwi, Pineapple, Grapes, Banana)","big":true},"decoder":{"title":"Scramble rule","body":"Read the digits in REVERSE order."}}'::jsonb, '[{"label":"4-digit vault code","accept":["1523"]}]'::jsonb, false, 3, 200, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🥝=3 🍍=2 🍇=5 🍌=1 → reversed → 1523', null, 25, 'published'), ('mission-fruit-2', 'fruit', 'mission', 'Fruit Slash', 'game', 1, array['any','food','healing','social','costa','sports','market']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍇","d":2},{"f":"🍊","d":9},{"f":"🥭","d":3},{"f":"🍍","d":5},{"f":"🍓","d":0},{"f":"🍎","d":4}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍓   🥭   🍎   🍊\n(Strawberry, Mango, Apple, Orange)","big":true},"decoder":{"title":"Scramble rule","body":"Subtract each digit from 9."}}'::jsonb, '[{"label":"4-digit vault code","accept":["9650"]}]'::jsonb, false, 3, 200, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍓=0 🥭=3 🍎=4 🍊=9 → 9 minus each digit → 9650', null, 25, 'published'), ('mission-fruit-3', 'fruit', 'mission', 'Fruit Slash', 'game', 1, array['any','food','healing','social','costa','sports','market']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍇","d":6},{"f":"🍌","d":4},{"f":"🥭","d":1},{"f":"🍒","d":2},{"f":"🍉","d":9},{"f":"🍊","d":8}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍇   🍊   🍒   🍉\n(Grapes, Orange, Cherry, Watermelon)","big":true},"decoder":{"title":"Scramble rule","body":"Add 3 to every digit and keep only the last digit (8 → 1)."}}'::jsonb, '[{"label":"4-digit vault code","accept":["9152"]}]'::jsonb, false, 3, 200, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍇=6 🍊=8 🍒=2 🍉=9 → +3 to each digit, last digit only → 9152', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

