insert into items(id, name, kind, description, params, price) values ('pistol', 'Pistol', 'weapon', 'Starts a standard puzzle duel. Never used up.', '{"damage":25,"tag":"duel_pistol","seconds":90,"consumable":false}'::jsonb, 0), ('smg', 'SMG', 'weapon', 'Fast duel: short timer, lower damage. One use.', '{"damage":20,"tag":"duel_smg","seconds":50,"consumable":true}'::jsonb, 40), ('sniper', 'Sniper', 'weapon', 'Hard logic duel: long timer, high damage. One use.', '{"damage":40,"tag":"duel_sniper","seconds":120,"consumable":true}'::jsonb, 60), ('shield', 'Shield', 'defense', 'Absorbs the next 30 damage.', '{"shield":30}'::jsonb, 35), ('medkit', 'Med Kit', 'heal', 'Restores 30 HP (max 100).', '{"heal":30}'::jsonb, 30), ('scanner', 'Intel Scanner', 'intel', 'Reveals every squad position (even jammed) for 60 s.', '{"seconds":60}'::jsonb, 30), ('jammer', 'Signal Jammer', 'stealth', 'Hides your squad from the public map for 120 s.', '{"seconds":120}'::jsonb, 30), ('beacon', 'Airdrop Beacon', 'airdrop', 'Your next airdrop win gives double coins.', '{}'::jsonb, 25), ('extract', 'Emergency Extract', 'move', 'Instantly relocate to the nearest safe zone location.', '{}'::jsonb, 40) on conflict (id) do update set name = excluded.name, kind = excluded.kind, description = excluded.description, params = excluded.params, price = excluded.price;
update teams t set level = l.level, bldg = case when l.level > 0 then l.building end from locations l where l.id = t.location_id and t.level <> l.level;

