insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-bottle-40', 'bottle', 'battle', 'Bottle Shoot Duel', 'game', 1, array['duel_smg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":3},{"c":"blue","d":0},{"c":"green","d":9},{"c":"yellow","d":1},{"c":"purple","d":7},{"c":"orange","d":4}],"ammo":6}},"intel":{"title":"Safe order","body":"ORANGE  →  BLUE  →  GREEN  →  YELLOW","big":true},"decoder":{"title":"Scramble rule","body":"Swap the first two digits and the last two digits."}}'::jsonb, '[{"label":"4-digit safe code","accept":["0419"]}]'::jsonb, false, 3, 75, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Orange=4 Blue=0 Green=9 Yellow=1 → pairs swapped → 0419', null, 25, 'published'), ('battle-bottle-41', 'bottle', 'battle', 'Bottle Shoot Duel', 'game', 1, array['duel_smg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":3},{"c":"blue","d":6},{"c":"green","d":0},{"c":"yellow","d":8},{"c":"purple","d":1},{"c":"orange","d":7}],"ammo":6}},"intel":{"title":"Safe order","body":"GREEN  →  YELLOW  →  PURPLE  →  BLUE","big":true},"decoder":{"title":"Scramble rule","body":"Add 2 to every digit and keep only the last digit (9 → 1)."}}'::jsonb, '[{"label":"4-digit safe code","accept":["2038"]}]'::jsonb, false, 3, 75, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Green=0 Yellow=8 Purple=1 Blue=6 → +2 to each digit → 2038', null, 25, 'published'), ('battle-bottle-42', 'bottle', 'battle', 'Bottle Shoot Duel', 'game', 1, array['duel_smg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":3},{"c":"blue","d":2},{"c":"green","d":0},{"c":"yellow","d":5},{"c":"purple","d":7},{"c":"orange","d":8}],"ammo":6}},"intel":{"title":"Safe order","body":"GREEN  →  RED  →  PURPLE  →  BLUE","big":true},"decoder":{"title":"Scramble rule","body":"Add 1 to every digit (9 becomes 0)."}}'::jsonb, '[{"label":"4-digit safe code","accept":["1483"]}]'::jsonb, false, 3, 75, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Green=0 Red=3 Purple=7 Blue=2 → +1 to each digit → 1483', null, 25, 'published'), ('battle-bottle-43', 'bottle', 'battle', 'Bottle Shoot Duel', 'game', 1, array['duel_smg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":1},{"c":"blue","d":9},{"c":"green","d":3},{"c":"yellow","d":5},{"c":"purple","d":2},{"c":"orange","d":8}],"ammo":6}},"intel":{"title":"Safe order","body":"RED  →  YELLOW  →  PURPLE  →  BLUE","big":true},"decoder":{"title":"Scramble rule","body":"Read the digits in REVERSE order."}}'::jsonb, '[{"label":"4-digit safe code","accept":["9251"]}]'::jsonb, false, 3, 75, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Red=1 Yellow=5 Purple=2 Blue=9 → reversed → 9251', null, 25, 'published'), ('mission-memcards-0', 'cards', 'mission', 'Memory Cards', 'game', 1, array['any','social','coffee','food','learning','office','hr']::text[], 'Scout flips cards to find matching pairs; every matched pair shows a letter. Intel knows which symbols spell the word. Decoder knows the twist.', '{"scout":{"title":"Memory Cards","body":"Tap two cards to flip them. A matching pair stays face up and shows its letter. Call out every symbol and letter.","game":{"type":"cards","deck":[{"s":"♥","l":"C"},{"s":"♦","l":"D"},{"s":"♠","l":"O"},{"s":"●","l":"J"},{"s":"♠","l":"O"},{"s":"★","l":"E"},{"s":"♣","l":"Q"},{"s":"●","l":"J"},{"s":"♥","l":"C"},{"s":"♦","l":"D"},{"s":"★","l":"E"},{"s":"♣","l":"Q"}]}},"intel":{"title":"Symbol order","body":"♥   ♠   ♦   ★\n(Heart, Spade, Diamond, Star)","big":true},"decoder":{"title":"The twist","body":"Read the letters exactly as they appear."}}'::jsonb, '[{"label":"4-letter word","accept":["CODE"]}]'::jsonb, false, 3, 200, 'Match all six pairs first, then let Intel read the symbols in order and the Decoder apply the twist.', '♥=C ♠=O ♦=D ★=E → Read the letters exactly as they appear → CODE', null, 25, 'published'), ('mission-memcards-1', 'cards', 'mission', 'Memory Cards', 'game', 1, array['any','social','coffee','food','learning','office','hr']::text[], 'Scout flips cards to find matching pairs; every matched pair shows a letter. Intel knows which symbols spell the word. Decoder knows the twist.', '{"scout":{"title":"Memory Cards","body":"Tap two cards to flip them. A matching pair stays face up and shows its letter. Call out every symbol and letter.","game":{"type":"cards","deck":[{"s":"♥","l":"Z"},{"s":"♣","l":"U"},{"s":"●","l":"V"},{"s":"♥","l":"Z"},{"s":"★","l":"C"},{"s":"★","l":"C"},{"s":"♦","l":"Q"},{"s":"♠","l":"F"},{"s":"♠","l":"F"},{"s":"●","l":"V"},{"s":"♣","l":"U"},{"s":"♦","l":"Q"}]}},"intel":{"title":"Symbol order","body":"★   ♥   ♣   ♠\n(Star, Heart, Club, Spade)","big":true},"decoder":{"title":"The twist","body":"Every letter was moved ONE step forward in the alphabet. Move each letter one step BACK (B → A, A → Z)."}}'::jsonb, '[{"label":"4-letter word","accept":["BYTE"]}]'::jsonb, false, 3, 200, 'Match all six pairs first, then let Intel read the symbols in order and the Decoder apply the twist.', '★=C ♥=Z ♣=U ♠=F → Every letter was moved ONE step forward in the alphabet → BYTE', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();

