insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-blackjack-0', 'blackjack', 'mission', 'Blackjack Table', 'cards', 2, array['any','social','boardroom','market','coffee']::text[], 'The dealer plays one hand from the shoe. Scout sees the cards in order, Decoder knows what each card is worth, Intel knows when the dealer stops. What is the dealer’s final total?', '{"scout":{"title":"The shoe (top first)","body":"5♠  6♥  K♦  3♠  Q♥  A♠  7♠  8♠","cards":["5♠","6♥","K♦","3♠","Q♥","A♠","7♠","8♠"]},"decoder":{"title":"Card values","body":"2–10 are worth their number.\nJ, Q, K are worth 10.\nA is worth 11 — unless that takes the total over 21, then it is worth 1."},"intel":{"title":"House rule","body":"The dealer takes cards from the top, one at a time, and STOPS as soon as the total is 16 or more.\nThe answer is the final total (it may be over 21 — a bust)."}}'::jsonb, '[{"label":"Dealer’s final total","accept":["21"]}]'::jsonb, false, 3, 200, 'Add one card at a time and check the total after each card.', '5♠ + 6♥ + K♦ = 21 (stops at 16+)', null, 25, 'published'), ('mission-blackjack-1', 'blackjack', 'mission', 'Blackjack Table', 'cards', 2, array['any','social','boardroom','market','coffee']::text[], 'The dealer plays one hand from the shoe. Scout sees the cards in order, Decoder knows what each card is worth, Intel knows when the dealer stops. What is the dealer’s final total?', '{"scout":{"title":"The shoe (top first)","body":"4♦  8♦  10♠  5♥  2♦  8♣  A♦  9♥","cards":["4♦","8♦","10♠","5♥","2♦","8♣","A♦","9♥"]},"decoder":{"title":"Card values","body":"2–10 are worth their number.\nJ, Q, K are worth 10.\nA is worth 11 — unless that takes the total over 21, then it is worth 1."},"intel":{"title":"House rule","body":"The dealer takes cards from the top, one at a time, and STOPS as soon as the total is 17 or more.\nThe answer is the final total (it may be over 21 — a bust)."}}'::jsonb, '[{"label":"Dealer’s final total","accept":["22"]}]'::jsonb, false, 3, 200, 'Add one card at a time and check the total after each card.', '4♦ + 8♦ + 10♠ = 22 (stops at 17+)', null, 25, 'published'), ('mission-blackjack-2', 'blackjack', 'mission', 'Blackjack Table', 'cards', 2, array['any','social','boardroom','market','coffee']::text[], 'The dealer plays one hand from the shoe. Scout sees the cards in order, Decoder knows what each card is worth, Intel knows when the dealer stops. What is the dealer’s final total?', '{"scout":{"title":"The shoe (top first)","body":"J♣  2♣  9♦  3♠  7♠  A♠  A♦  2♥","cards":["J♣","2♣","9♦","3♠","7♠","A♠","A♦","2♥"]},"decoder":{"title":"Card values","body":"2–10 are worth their number.\nJ, Q, K are worth 10.\nA is worth 11 — unless that takes the total over 21, then it is worth 1."},"intel":{"title":"House rule","body":"The dealer takes cards from the top, one at a time, and STOPS as soon as the total is 18 or more.\nThe answer is the final total (it may be over 21 — a bust)."}}'::jsonb, '[{"label":"Dealer’s final total","accept":["21"]}]'::jsonb, false, 3, 200, 'Add one card at a time and check the total after each card.', 'J♣ + 2♣ + 9♦ = 21 (stops at 18+)', null, 25, 'published'), ('mission-blackjack-3', 'blackjack', 'mission', 'Blackjack Table', 'cards', 2, array['any','social','boardroom','market','coffee']::text[], 'The dealer plays one hand from the shoe. Scout sees the cards in order, Decoder knows what each card is worth, Intel knows when the dealer stops. What is the dealer’s final total?', '{"scout":{"title":"The shoe (top first)","body":"9♠  5♣  10♠  8♦  2♥  Q♦  A♣  8♠","cards":["9♠","5♣","10♠","8♦","2♥","Q♦","A♣","8♠"]},"decoder":{"title":"Card values","body":"2–10 are worth their number.\nJ, Q, K are worth 10.\nA is worth 11 — unless that takes the total over 21, then it is worth 1."},"intel":{"title":"House rule","body":"The dealer takes cards from the top, one at a t