insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-cardsharp-2', 'cardsharp', 'mission', 'Card Sharp', 'cards', 1, array['any','office','learning','social','glass']::text[], 'Six cards lie face up. Intel knows which three count, Decoder knows how to score them. Add up the score.', '{"scout":{"title":"The table (left to right)","body":"1: 7♣   2: 6♦   3: J♠   4: 5♣   5: Q♠   6: 4♥","cards":["7♣","6♦","J♠","5♣","Q♠","4♥"]},"intel":{"title":"Cards that count","body":"Positions 1, 2, 4 (counting from the LEFT).","big":true},"decoder":{"title":"Scoring","body":"A=1, J=11, Q=12, K=13. Face cards (J, Q, K) count 10 instead."}}'::jsonb, '[{"label":"Total score","accept":["18"]}]'::jsonb, false, 3, 200, 'Scout reads out the three cards Intel names; Decoder scores each one; the captain adds.', '7♣=7 + 6♦=6 + 5♣=5 = 18 (faces 10)', null, 25, 'published'), ('mission-cardsharp-3', 'cardsharp', 'mission', 'Card Sharp', 'cards', 1, array['any','office','learning','social','glass']::text[], 'Six cards lie face up. Intel knows which three count, Decoder knows how to score them. Add up the score.', '{"scout":{"title":"The table (left to right)","body":"1: J♠   2: 2♦   3: 7♠   4: 8♥   5: 7♦   6: 6♠","cards":["J♠","2♦","7♠","8♥","7♦","6♠"]},"intel":{"title":"Cards that count","body":"Positions 2, 4, 6 (counting from the LEFT).","big":true},"decoder":{"title":"Scoring","body":"A=1, J=11, Q=12, K=13. Add 5 for every ♣ club."}}'::jsonb, '[{"label":"Total score","accept":["16"]}]'::jsonb, false, 3, 200, 'Scout reads out the three cards Intel names; Decoder scores each one; the captain adds.', '2♦=2 + 8♥=8 + 6♠=6 = 16 (clubs +5)', null, 25, 'published'), ('mission-cardsharp-4', 'cardsharp', 'mission', 'Card Sharp', 'cards', 1, array['any','office','learning','social','glass']::text[], 'Six cards lie face up. Intel knows which three count, Decoder knows how to score them. Add up the score.', '{"scout":{"title":"The table (left to right)","body":"1: 10♥   2: 6♣   3: 10♣   4: J♠   5: 9♦   6: 7♠","cards":["10♥","6♣","10♣","J♠","9♦","7♠"]},"intel":{"title":"Cards that count","body":"Positions 4, 5, 6 (counting from the LEFT).","big":true},"decoder":{"title":"Scoring","body":"A=1, J=11, Q=12, K=13. RED cards (♥ ♦) count DOUBLE."}}'::jsonb, '[{"label":"Total score","accept":["36"]}]'::jsonb, false, 3, 200, 'Scout reads out the three cards Intel names; Decoder scores each one; the captain adds.', 'J♠=11 + 9♦=18 + 7♠=7 = 36 (red ×2)', null, 25, 'published'), ('mission-cardsharp-5', 'cardsharp', 'mission', 'Card Sharp', 'cards', 1, array['any','office','learning','social','glass']::text[], 'Six cards lie face up. Intel knows which three count, Decoder knows how to score them. Add up the score.', '{"scout":{"title":"The table (left to right)","body":"1: 5♦   2: 8♣   3: 8♦   4: Q♣   5: 4♣   6: 3♠","cards":["5♦","8♣","8♦","Q♣","4♣","3♠"]},"intel":{"title":"Cards that count","body":"Positions 2, 3, 5 (counting from the LEFT).","big":true},"decoder":{"title":"Scoring","body":"A=1, J=11, Q=12, K=13. Every ♠ spade counts 0."}}'::jsonb, '[{"label":"Total score","accept":["20"]}]'::jsonb, false, 3, 200, 'Scout reads out the three cards Intel names; Decoder scores each one; the captain adds.', '8♣=8 + 8♦=8 + 4♣=4 = 20 (spades 0)', null, 25, 'published'), ('mission-cardsharp-6', 'cardsharp', 'mission', 'Card Sharp', 'cards', 1, array['any','office','learning','social','glass']::text[], 'Six cards lie face up. Intel knows which three count, Decoder knows how to score them. Add up the score.', '{"scout":{"title":"The table (left to right)","body":"1: 10♠   2: Q♥   3: Q♣   4: 5♣   5: 3♣   6: 6♥","cards":["10♠","Q♥","Q♣","5♣","3♣","6♥"]},"intel":{"title":"Cards that count","body":"Positions 2, 3, 5 (counting from the LEFT).","big":true},"decoder":{"title":"Scoring","body":"A=1, J=11, Q=12, K=13. Face cards (J, Q, K) count 10 instead.