insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pattern-1', 'pattern', 'mission', 'Pattern Lock', 'logic', 1, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[6,3,0,4,1]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo of the lock was taken UPSIDE DOWN (turned 180°)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  8  9\n4  5  6\n1  2  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["96352"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 2-5-8-4-7 → 96352', null, 25, 'published'), ('mission-pattern-2', 'pattern', 'mission', 'Pattern Lock', 'logic', 1, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[6,4,1,0,3]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo is a MIRROR image (left and right swapped)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n5  1  3\n2  8  4\n7  9  6"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["68134"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 8-4-1-2-5 → 68134', null, 25, 'published'), ('mission-pattern-3', 'pattern', 'mission', 'Pattern Lock', 'logic', 2, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[7,3,1,4,2]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo is turned 90° CLOCKWISE (the top row of the photo is the left column of the lock)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  8  9\n4  5  6\n1  2  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["62457"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 5-7-3-4-0 → 62457', null, 25, 'published'), ('mission-pattern-4', 'pattern', 'mission', 'Pattern Lock', 'logic', 1, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[5,2,1,3,4]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo of the lock is the right way up."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n4  2  3\n7  6  5\n8  9  1"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["53276"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 5-2-1-3-4 → 53276', null, 25, 'published'), ('mission-pattern-5', 'pattern', 'mission', 'Pattern Lock', 'logic', 1, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[5,4,6,3]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo of the lock was taken UPSIDE DOWN (turned 180°)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  8  9\n4  5  6\n1  2  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["4596"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 3-4-2-5 → 4596', null, 25, 'published'), ('mission-pattern-6', 'pattern', 'mission', 'Pattern Lock', 'logic', 1, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[7,3,6,4,5,8]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo is a MIRROR image (left and right swapped)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n6  5  9\n3  8  1\n4  2  7"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["217834"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 7-5-8-4-3-6 → 217834', null, 25, 'publi