-- ═══ 0800_freefall_lift.sql ═══
alter table teams add column if not exists jump_at timestamptz;
alter table teams add column if not exists land_at timestamptz;
drop function if exists _defaults_v6();
alter function _defaults() rename to _defaults_v6;
create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v6() || jsonb_build_object( 'move_speed', 20, 'foot_speed', 13, 'fall_seconds', 18, 'glide_speed', 18) $$;
create or replace function _br_roles_gate(p_arena uuid) returns boolean language plpgsql as $$ begin if (select phase from arenas where id = p_arena) <> 'play' then return false; end if; return _auto_roles(p_arena); end $$;
create or replace function _jump_now(p_team uuid, p_xy float8[]) returns timestamptz language plpgsql as $$ declare t teams; v_land timestamptz; begin select * into t from teams where id = p_team for update; v_land := now() + _secs(_cfg(t.event_id, 'fall_seconds')); update teams set jump_at = now(), land_at = v_land, pos_x = p_xy[1], pos_y = p_xy[2], pos_at = now(), vel_x = 0, vel_y = 0, state = 'idle', travel_to = null, travel_arrive_at = null, vehicle = 'none', buggy_x = null, buggy_y = null, level = 0, bldg = null where id = p_team; perform _feed(t.arena_id, 'squad.jumped', jsonb_build_object('team', t.number)); perform _ping_team(p_team, 'move'); return v_land; end $$;
create or replace function captain_jump(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; pl float8[]; v_land timestamptz; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.dropped or t.jump_at is not null then raise exception 'ALREADY_JUMPED'; end if; pl := _plane_xy(a); if pl is null or pl[3] >= 0.99 then raise exception 'PLANE_GONE'; end if; if pl[1] < 0.02 or pl[1] > 0.98 or pl[2] < 0.02 or pl[2] > 0.98 then raise exception 'NOT_OVER_CAMPUS'; end if; v_land := _jump_now(t.id, array[pl[1], pl[2]]); return jsonb_build_object('land_at', v_land, 'x', pl[1], 'y', pl[2]); end $$;
drop function if exists _captain_steer_v6(text, double precision, double precision, double precision, double precision);
alter function captain_steer(text, double precision, double precision, double precision, double precision) rename to _captain_steer_v6;
create function captain_steer(p_token text, p_x double precision, p_y double precision, p_vx double precision default 0, p_vy double precision default 0) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; dt float8; maxd float8; d float8; nx float8; ny float8; v_spd float8; v_vx float8; v_vy float8; v_vm float8; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; if t.dropped or t.jump_at is null then return _captain_steer_v6(p_token, p_x, p_y, p_vx, p_vy); end if; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if p_x is null or p_y is null or p_x = 'NaN'::float8 or p_y = 'NaN'::float8 or abs(p_x) = 'Infinity'::float8 or abs(p_y) = 'Infinity'::float8 then raise exception 'BAD_REQUEST'; end if; v_spd := _cfg(t.event_id, 'glide_speed') / 1000.0; dt := least(4, greatest(0, extract(epoch from now() - coalesce(t.pos_at, now() - interval '1 second')))); maxd := v_spd * dt * 1.25 + 0.003; nx := greatest(0.02, least(0.98, p_x)); ny := greatest(0.02, least(0.98, p_y)); d := sqrt((nx - t.pos_x) ^ 2 + (ny - t.pos_y) ^ 2); if d > maxd then nx := t.pos_x + (nx - t.pos_x) * maxd / d; ny := t.pos_y + (ny - t.pos_y) * maxd / d; end if; v_vx := coalesce(p_vx, 0); v_vy := coalesce(p_vy, 0); if v_vx = 'NaN'::float8 or v_vy = 'NaN'::float8 or abs(v_vx) = 'Infinity'::float8 or abs(v_vy) = 'Infinity'::float8 then v_vx := 0; v_vy := 0; end if; v_vm := sqrt(v_vx ^ 2 + v_vy ^ 2); if v_vm > v_spd * 1.1 then v_vx := v_vx * v_spd * 1.1 / v_vm; v_vy := v_vy * v_spd * 1.1 / v_vm; end if; update teams set pos_x = nx, pos_y = ny, pos_at = now(), vel_x = v_vx, vel_y = v_vy where id = t.id; if t.last_steer_ping is null or t.last_steer_ping < now() - interval '2 seconds' then update teams set last_steer_ping = now() where id = t.id; perform _ping_team(t.id, 'move'); end if; return jsonb_build_object('x', nx, 'y', ny, 'air', true, 'land_at', t.land_at, 'level', 0, 'clamped', abs(nx - p_x) > 0.0005 or abs(ny - p_y) > 0.0005); end $$;
create or replace function _land(p_team uuid) returns void language plpgsql as $$ declare t teams; x float8; y float8; b buildings; xy float8[]; v_loc text; begin select * into t from teams where id = p_team for update; x := t.pos_x; y := t.pos_y; select * into b from buildings where x between x0 and x1 and y between y0 and y1 limit 1; if b.id is not null then x := b.door_x; y := b.door_y; end if; xy := _buggy_bay(t.number, x, y); v_loc := _loc_at3(t.arena_id, t.event_id, x, y, 0, null); update teams set dropped = true, jump_at = null, land_at = null, pos_x = x, pos_y = y, pos_at = now(), vel_x = 0, vel_y = 0, level = 0, bldg = null, state = 'idle', location_id = v_loc, vehicle = 'none', buggy_x = xy[1], buggy_y = xy[2], visit_missions = 0, protected_until = greatest(coalesce(protected_until, now()), now() + interval '8 seconds') where id = p_team; perform _feed(t.arena_id, 'squad.landed', jsonb_build_object('team', t.number, 'location', v_loc)); perform _ping_team(p_team, 'landed'); end $$;
create or replace function captain_lift(p_token text, p_level int) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; r jsonb; v_dir int; n int := 0; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id; if p_level is null or p_level < 0 or p_level > 20 then raise exception 'NO_FLOOR'; end if; if p_level = t.level then raise exception 'ALREADY_HERE'; end if; v_dir := case when p_level > t.level then 1 else -1 end; loop r := captain_stairs(p_token, v_dir); n := n + 1; exit when (r ->> 'level')::int = p_level or n > 20; end loop; return r || jsonb_build_object('floors', n); end $$;
create or replace function _team_extra(t teams) returns jsonb language sql stable as $$ select jsonb_build_object('vehicle', t.vehicle, 'kills', t.kills, 'buggy', case when t.buggy_x is not null and t.vehicle <> 'in' then jsonb_build_array(t.buggy_x, t.buggy_y) when t.dropped and t.vehicle = 'none' then to_jsonb(_buggy_bay(t.number, (_team_xy(t))[1], (_team_xy(t))[2])) end, 'in_plane', not t.dropped and t.jump_at is null and t.state <> 'traveling', 'parachute', not t.dropped and (t.jump_at is not null or t.state = 'traveling'), 'jump_at', t.jump_at, 'land_at', case when t.jump_at is not null then t.land_at when not t.dropped and t.state = 'traveling' then t.travel_arrive_at end, 'weapon', _weapon(t.id), 'fight_at', t.fight_at) $$;
create or replace function arena_positions(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_scan boolean; begin p := _auth_player(p_token); select * into t from teams where id = p.team_id; if exists (select 1 from bots where arena_id = t.arena_id) then perform _tick(t.arena_id); end if; v_scan := t.scan_until is not null and t.scan_until > now(); return jsonb_build_object('server_now', now(), 'squads', (select coalesce(jsonb_agg(jsonb_build_object( 'id', tm.id, 'n', tm.number, 'level', tm.level, 'bldg', tm.bldg, 'state', tm.state, 'pos', to_jsonb(_team_xy(tm)), 'age', case when tm.state = 'idle' and tm.pos_at is not null then round(extract(epoch from now() - tm.pos_at)::numeric, 2) end, 'vel', case when tm.state = 'traveling' and tm.travel_arrive_at > now() and l.id is not null then jsonb_build_array((l.x - coalesce(tm.travel_fx, l.x)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at)), (l.y - coalesce(tm.travel_fy, l.y)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at))) when tm.state = 'idle' and tm.pos_at > now() - interval '3 seconds' and (tm.vel_x <> 0 or tm.vel_y <> 0) then jsonb_build_array(tm.vel_x, tm.vel_y) end, 'hp', tm.hp, 'shield', tm.shield, 'veh', tm.vehicle, 'buggy', case when tm.buggy_x is not null and tm.vehicle = 'parked' then jsonb_build_array(tm.buggy_x, tm.buggy_y) end, 'plane', not tm.dropped and tm.jump_at is null and tm.state <> 'traveling', 'chute', not tm.dropped and (tm.jump_at is not null or tm.state = 'traveling'), 'jump_at', tm.jump_at, 'land_at', case when tm.jump_at is not null then tm.land_at when not tm.dropped and tm.state = 'traveling' then tm.travel_arrive_at end, 'fight', tm.fight_at > now() - interval '4 seconds')), '[]'::jsonb) from teams tm left join locations l on l.id = tm.travel_to where tm.arena_id = t.arena_id and tm.ready and (tm.id = t.id or v_scan or tm.location_id = t.location_id or tm.jammed_until is null or tm.jammed_until < now() or tm.fight_at > now() - interval '4 seconds' or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = tm.id) or (al.team_b = t.id and al.team_a = tm.id)))))); end $$;
create or replace function _br_step(p_arena uuid) returns boolean language plpgsql as $$ declare a arenas; r record; pl float8[]; v_changed boolean := false; xy float8[]; begin select * into a from arenas where id = p_arena; if a.id is null then return false; end if; if a.phase = 'shuttle' and (a.overlay -> 'flight' ->> 't1') is distinct from to_jsonb(a.shuttle_arrive_at) #>> '{}' then update arenas set overlay = overlay || jsonb_build_object('flight', jsonb_build_object( 't0', a.shuttle_arrive_at - _secs(_cfg(a.event_id, 'shuttle_seconds')), 't1', a.shuttle_arrive_at)) where id = p_arena; v_changed := true; end if; if a.phase = 'play' and _auto_roles(p_arena) then v_changed := true; end if; if a.phase in ('lobby', 'boarding') and (a.plane_t0 is not null or a.zone_shrink_until is not null or a.overlay ? 'plane') then update arenas set plane_t0 = null, plane_t1 = null, zone_shrink_from = null, zone_shrink_until = null, overlay = overlay - 'plane' - 'flight' where id = p_arena; update teams set vehicle = 'none', buggy_x = null, buggy_y = null, kills = 0, fight_at = null, jump_at = null, land_at = null where arena_id = p_arena; v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'br_mode') = 1 and (a.plane_t0 is null or a.plane_t1 < a.play_started_at) then perform _plane_launch(p_arena); v_changed := true; select * into a from arenas where id = p_arena; end if; if a.phase = 'play' then for r in select id from teams where arena_id = p_arena and not dropped and jump_at is not null and land_at <= now() loop perform _land(r.id); v_changed := true; end loop; for r in select t.id, t.number, l.x, l.y from teams t join locations l on l.id = t.travel_to where t.arena_id = p_arena and not t.dropped and t.state = 'traveling' and t.travel_arrive_at <= now() loop xy := _buggy_bay(r.number, r.x, r.y); update teams set pos_x = r.x + ((r.number * 37) % 9 - 4) * 0.0012, pos_y = r.y + ((r.number * 53) % 9 - 4) * 0.0012, pos_at = now(), vel_x = 0, vel_y = 0, vehicle = case when _cfg(a.event_id, 'br_mode') = 1 then 'none' else 'in' end, buggy_x = xy[1], buggy_y = xy[2] where id = r.id; end loop; update teams t set pos_x = l.x, pos_y = l.y, pos_at = now() from locations l where l.id = t.travel_to and t.arena_id = p_arena and t.dropped and t.state = 'traveling' and t.travel_arrive_at <= now(); pl := _plane_xy(a); if pl is not null and pl[3] >= 0.8 then for r in select id from teams where arena_id = p_arena and ready and not dropped and jump_at is null and state = 'idle' loop perform _jump_now(r.id, array[least(0.96, greatest(0.04, pl[1])), least(0.96, greatest(0.04, pl[2]))]); v_changed := true; end loop; end if; end if; if a.zone_shrink_until is not null and a.zone_shrink_until > now() and (a.overlay -> 'zone' ->> 'shrink_until') is null then perform _zone_publish(p_arena); v_changed := true; end if; if a.zone_shrink_until is not null and a.zone_shrink_until <= now() and (a.overlay -> 'zone' ->> 'shrink_until') is not null then perform _zone_publish(p_arena); v_changed := true; end if; return v_changed; end $$;
do $$ declare d text; n text; i int; j int; k int; begin d := pg_get_functiondef('_bot_act(uuid)'::regprocedure); i := position('if not t.dropped then' in d); j := position('update bots set goal = null, done_loc = null, wait_until = null where team_id = t.id;' in d); if i = 0 or j = 0 or j < i then raise exception 'v7: could not find the jump in _bot_act'; end if; k := j + position('end if;' in substr(d, j)) + length('end if;') - 1; n := substr(d, 1, i - 1) || 'if not t.dropped then
    if t.jump_at is null then
      pl := _plane_xy(a);
      if pl is null or pl[1] not between 0.06 and 0.94 or pl[2] not between 0.06 and 0.94 or random() > 0.14 then return; end if;
      perform captain_jump(tok);
      c := _zone_circle(a.event_id, a.zone_stage);
      select l.id into v_goal from locations l
      where l.enabled and l.kind not in (''start'', ''stairs'') and l.level = 0 and _in_circle(c, l.x, l.y)
        and sqrt((l.x - pl[1]) ^ 2 + (l.y - pl[2]) ^ 2) < _cfg(t.event_id, ''glide_speed'') / 1000.0 * _cfg(t.event_id, ''fall_seconds'') * 0.8
      order by random() limit 1;
      update bots set goal = v_goal, goal_at = now(), done_loc = null, wait_until = null where team_id = t.id;
      return;
    end if;
    select * into g from locations where id = b.goal;
    if g.id is null then return; end if;
    spd := _cfg(t.event_id, ''glide_speed'') / 1000.0;
    dt := least(3.0, greatest(0.3, extract(epoch from now() - coalesce(t.pos_at, now() - interval ''1 second''))));
    d := sqrt((g.x - cur[1]) ^ 2 + (g.y - cur[2]) ^ 2);
    if d > 0.002 then
      stepd := least(d, spd * dt);
      perform captain_steer(tok, cur[1] + (g.x - cur[1]) * stepd / d, cur[2] + (g.y - cur[2]) * stepd / d, (g.x - cur[1]) / d * spd, (g.y - cur[2]) / d * spd);
    end if;
    return;
  end if;' || substr(d, k + 1); if n = d then raise exception 'v7: could not patch the dummy squads (_bot_act)'; end if; execute n; end $$;
create or replace function _bots_claim_roles(p_arena uuid) returns void language plpgsql as $$ declare r record; v_role text; begin for r in select p.id, p.team_id, bp.idx from players p join bot_players bp on bp.player_id = p.id join bots b on b.team_id = p.team_id where b.arena_id = p_arena and not b.manual and p.active and p.role is null and random() < 0.3 loop v_role := (array['captain', 'scout', 'decoder', 'intel'])[r.idx]; begin update players set role = v_role where id = r.id and role is null and not exists (select 1 from players q where q.team_id = r.team_id and q.active and q.role = v_role); if found then perform _ping_team(r.team_id, 'roles'); end if; exception when others then null; end; end loop; end $$;
create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare v boolean; w boolean; ph text; begin w := _br_step(p_arena); v := _tick_core(p_arena, p_force); if _br_step(p_arena) or w then v := true; perform _ping_arena(p_arena, 'tick'); end if; if exists (select 1 from bots where arena_id = p_arena) then select phase into ph from arenas where id = p_arena; if ph = 'shuttle' then perform _bots_claim_roles(p_arena); end if; if _bots_step(p_arena) then v := true; end if; end if; return v; end $$;
do $$ declare d text; n text; begin d := pg_get_functiondef('claim_role(text, text)'::regprocedure); n := replace(d, 'if a.phase <> ''roles'' or now() >= a.roles_deadline then raise exception ''ROLES_CLOSED''; end if;', 'if not (a.phase = ''shuttle'' or (a.phase = ''roles'' and now() < a.roles_deadline)) then raise exception ''ROLES_CLOSED''; end if;'); if n = d then raise exception 'v7: could not patch claim_role'; end if; execute n; end $$;
do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;

-- ═══ 0900_online.sql ═══
alter table teams add column if not exists squad_code text;
alter table teams add column if not exists open_squad boolean not null default false;
alter table players add column if not exists role2 text;
create unique index if not exists teams_code_uniq on teams(event_id, squad_code) where squad_code is not null;
create table if not exists online_members ( event_id uuid not null references events(id) on delete cascade, emp_id text not null check (emp_id ~ '^[0-9]{10}$'), email text not null check (char_length(email) between 5 and 120), player_id uuid references players(id) on delete set null, name text not null, first_joined_at timestamptz not null default now(), primary key (event_id, emp_id) );
create unique index if not exists online_members_email_uniq on online_members(event_id, lower(email));
create index if not exists online_members_player_idx on online_members(player_id);
create table if not exists squad_chat ( id bigserial primary key, team_id uuid not null references teams(id) on delete cascade, player_id uuid references players(id) on delete set null, name text not null, kind text not null default 'msg' check (kind in ('msg', 'ping', 'system')), body text not null check (char_length(body) between 1 and 240), at timestamptz not null default now() );
create index if not exists squad_chat_team_idx on squad_chat(team_id, id);
do $$ declare t text; begin foreach t in array array['online_members', 'squad_chat'] loop execute format('alter table %I enable row level security', t); execute format('revoke all on table %I from anon, authenticated', t); end loop; end $$;
drop function if exists _defaults_v7();
alter function _defaults() rename to _defaults_v7;
create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v7() || jsonb_build_object( 'online', 0, 'online_max_maps', 8, 'email_domain', '') $$;
create or replace function _squad_code() returns text language sql volatile as $$ select string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + floor(random() * 31)::int, 1), '') from generate_series(1, 4) $$;
create or replace function _online_size(p_team uuid) returns int language sql stable as $$ select count(*)::int from players where team_id = p_team and active $$;
create or replace function _online_arena(p_ev uuid) returns uuid language plpgsql as $$ declare v_arena uuid; v_size int; v_n int; begin v_size := _cfg(p_ev, 'arena_size'); select a.id into v_arena from arenas a where a.event_id = p_ev and a.phase in ('lobby', 'boarding') and (select count(*) from teams t where t.arena_id = a.id) < v_size order by a.number limit 1; if v_arena is not null then return v_arena; end if; select count(*) into v_n from arenas where event_id = p_ev; if v_n >= _cfg(p_ev, 'online_max_maps') then raise exception 'ALL_MAPS_FULL'; end if; insert into arenas(event_id, number, name) values (p_ev, (select coalesce(max(number), 0) + 1 from arenas where event_id = p_ev), 'Map ' || (select coalesce(max(number), 0) + 1 from arenas where event_id = p_ev)) returning id into v_arena; insert into audit_log(event_id, arena_id, actor, action) values (p_ev, v_arena, 'online', 'map_opened'); return v_arena; end $$;
create or replace function _online_new_team(p_ev uuid, p_open boolean) returns teams language plpgsql as $$ declare v_arena uuid; v_team teams; v_salt text := _new_token(); v_code text; i int := 0; begin v_arena := _online_arena(p_ev); loop v_code := _squad_code(); i := i + 1; exit when not exists (select 1 from teams where event_id = p_ev and squad_code = v_code) or i > 20; end loop; insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash, squad_code, open_squad) values (p_ev, v_arena, (select coalesce(max(number), 0) + 1 from teams where event_id = p_ev), null, v_salt, _hash(v_salt || _new_token()), v_code, p_open) returning * into v_team; perform _add_item(v_team.id, 'pistol', 1); perform _add_item(v_team.id, 'medkit', 1); return v_team; end $$;
create or replace function _online_refresh(p_team uuid) returns void language plpgsql as $$ declare n int; t teams; begin select * into t from teams where id = p_team; if t.id is null then return; end if; n := _online_size(p_team); if n = 0 then delete from teams where id = p_team; return; end if; update teams set ready = n >= 3, roster_locked = n >= 4 where id = p_team; if n >= 3 and not t.ready then perform _feed(t.arena_id, 'team.ready', jsonb_build_object('team', t.number)); end if; perform _ping_team(p_team, 'roster'); perform _ping_arena(t.arena_id, 'roster'); end $$;
create or replace function _online_move(p_player uuid, p_team uuid) returns void language plpgsql as $$ declare v_old uuid; begin select team_id into v_old from players where id = p_player; if v_old = p_team then return; end if; update players set team_id = p_team, role = null, role2 = null where id = p_player; insert into squad_chat(team_id, name, kind, body) select p_team, 'Hexa Air', 'system', display_name || ' joined the squad' from players where id = p_player; perform _online_refresh(v_old); perform _online_refresh(p_team); end $$;
create or replace function online_join(p_event_code text, p_emp_id text, p_email text, p_name text, p_mode text, p_code text default null, p_consent boolean default false, p_existing_token text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare e events; m online_members; p players; t teams; v_token text; v_email text; v_emp text; v_name text; v_domains text; v_ok boolean; d text; v_phase text; v_started boolean; begin select * into e from events where code = upper(trim(coalesce(p_event_code, ''))); if e.id is null then raise exception 'NO_EVENT'; end if; if _cfg(e.id, 'online') <> 1 then raise exception 'NOT_ONLINE_EVENT'; end if; perform pg_advisory_xact_lock(hashtext('online:' || e.id::text)); v_started := coalesce(_cfg(e.id, 'online_started'), 0) = 1; v_emp := regexp_replace(coalesce(p_emp_id, ''), '\s', '', 'g'); v_email := lower(trim(coalesce(p_email, ''))); v_name := trim(coalesce(p_name, '')); if v_emp !~ '^[0-9]{10}$' then raise exception 'BAD_EMP_ID'; end if; if v_email !~ '^[a-z0-9._%+''-]+@[a-z0-9.-]+\.[a-z]{2,}$' or char_length(v_email) > 120 then raise exception 'BAD_EMAIL'; end if; v_domains := coalesce(_cfg_text(e.id, 'email_domain'), ''); if v_domains <> '' then v_ok := false; foreach d in array string_to_array(replace(lower(v_domains), ' ', ''), ',') loop if d <> '' and (v_email like '%@' || d or v_email like '%.' || d) then v_ok := true; end if; end loop; if not v_ok then raise exception 'EMAIL_DOMAIN'; end if; end if; if (select count(*) from pin_failures where event_id = e.id and team_number = -1000 and at > now() - interval '5 minutes') >= 40 then raise exception 'LOCKED_OUT'; end if; select * into m from online_members where event_id = e.id and emp_id = v_emp; if m.emp_id is not null and lower(m.email) <> v_email then insert into pin_failures(event_id, team_number) values (e.id, -1000); return jsonb_build_object('error', 'EMP_ID_TAKEN'); end if; if m.emp_id is null and exists (select 1 from online_members where event_id = e.id and lower(email) = v_email) then return jsonb_build_object('error', 'EMAIL_TAKEN'); end if; if m.player_id is not null then select * into p from players where id = m.player_id and active; end if; if p.id is not null then select * into t from teams where id = p.team_id; select phase into v_phase from arenas where id = t.arena_id; if p_existing_token is not null and p.session_hash = _hash(p_existing_token) then v_token := p_existing_token; else v_token := _new_token(); update players set session_hash = _hash(v_token) where id = p.id; end if; if coalesce(p_mode, 'rejoin') <> 'rejoin' and v_phase in ('lobby', 'boarding') and not v_started then if p_mode = 'join' then select * into t from teams where event_id = e.id and squad_code = upper(trim(coalesce(p_code, ''))); if t.id is null then insert into pin_failures(event_id, team_number) values (e.id, -1000); return jsonb_build_object('error', 'BAD_SQUAD_CODE', 'token', v_token); end if; if (select phase from arenas where id = t.arena_id) not in ('lobby', 'boarding') then return jsonb_build_object('error', 'SQUAD_GONE', 'token', v_token); end if; if t.id <> p.team_id and _online_size(t.id) >= 4 then return jsonb_build_object('error', 'TEAM_FULL', 'token', v_token); end if; perform _online_move(p.id, t.id); elsif p_mode = 'create' then t := _online_new_team(e.id, false); perform _online_move(p.id, t.id); elsif p_mode = 'queue' and not (select open_squad from teams where id = p.team_id) then select x.* into t from teams x join arenas a on a.id = x.arena_id where x.event_id = e.id and x.open_squad and a.phase in ('lobby', 'boarding') and x.id <> p.team_id and (select count(*) from players q where q.team_id = x.id and q.active) between 1 and 3 order by (select count(*) from players q where q.team_id = x.id and q.active) desc, x.created_at limit 1; if t.id is null then t := _online_new_team(e.id, true); end if; perform _online_move(p.id, t.id); end if; end if; select * into t from teams where id = (select team_id from players where id = p.id); return jsonb_build_object('token', v_token, 'team', t.number, 'code', t.squad_code, 'rejoined', true); end if; if p_mode = 'rejoin' then return jsonb_build_object('error', 'NOT_REGISTERED'); end if; if not coalesce(p_consent, false) then raise exception 'CONSENT_REQUIRED'; end if; if char_length(v_name) < 1 or char_length(v_name) > 40 then raise exception 'BAD_NAME'; end if; if p_mode = 'join' then select * into t from teams where event_id = e.id and squad_code = upper(trim(coalesce(p_code, ''))); if t.id is null then insert into pin_failures(event_id, team_number) values (e.id, -1000); return jsonb_build_object('error', 'BAD_SQUAD_CODE'); end if; if (v_started and not _online_open(t.id)) or (not v_started and (select phase from arenas where id = t.arena_id) not in ('lobby', 'boarding')) then return jsonb_build_object('error', 'SQUAD_GONE'); end if; if _online_size(t.id) >= 4 then return jsonb_build_object('error', 'TEAM_FULL'); end if; elsif v_started and p_mode = 'create' then raise exception 'GAME_STARTED'; elsif v_started and p_mode = 'queue' then select * into t from teams where id = _online_late_team(e.id); if t.id is null then raise exception 'NO_OPEN_SEATS'; end if; elsif p_mode = 'create' then t := _online_new_team(e.id, false); elsif p_mode = 'queue' then select x.* into t from teams x join arenas a on a.id = x.arena_id where x.event_id = e.id and x.open_squad and a.phase in ('lobby', 'boarding') and (select count(*) from players q where q.team_id = x.id and q.active) between 1 and 3 order by (select count(*) from players q where q.team_id = x.id and q.active) desc, a.number, x.created_at limit 1; if t.id is null then t := _online_new_team(e.id, true); end if; else raise exception 'BAD_MODE'; end if; if exists (select 1 from players where team_id = t.id and active and lower(display_name) = lower(v_name)) then v_name := left(v_name, 36) || ' ' || right(v_emp, 3); end if; v_token := _new_token(); insert into players(team_id, display_name, session_hash, consent) values (t.id, v_name, _hash(v_token), true) returning * into p; if m.emp_id is null then insert into online_members(event_id, emp_id, email, player_id, name) values (e.id, v_emp, v_email, p.id, v_name); else update online_members set player_id = p.id, name = v_name where event_id = e.id and emp_id = v_emp; end if; insert into squad_chat(team_id, name, kind, body) values (t.id, 'Hexa Air', 'system', v_name || ' checked in'); perform _feed(t.arena_id, 'player.joined', jsonb_build_object('team', t.number, 'count', _online_size(t.id))); if v_started then update players set role2 = null, role2_bot = false where team_id = t.id and role2 is not null; update teams set ready = true, roster_locked = _online_size(t.id) >= 4 where id = t.id; insert into squad_chat(team_id, name, kind, body) values (t.id, 'Hexa Air', 'system', '🪂 ' || v_name || ' joined late — welcome!'); perform _ping_team(t.id, 'roster'); return jsonb_build_object('token', v_token, 'team', t.number, 'code', t.squad_code, 'rejoined', false, 'late', true); end if; perform _online_refresh(t.id); return jsonb_build_object('token', v_token, 'team', t.number, 'code', t.squad_code, 'rejoined', false); end $$;
create or replace function _online_seal(p_arena uuid) returns jsonb language plpgsql as $$ declare u record; v record; x record; v_t uuid; v_need int; v_moved int := 0; v_left int := 0; begin perform pg_advisory_xact_lock(hashtext('online:' || (select event_id from arenas where id = p_arena)::text)); for u in select t.id from teams t where t.arena_id = p_arena order by _online_size(t.id) desc, t.open_squad, t.created_at loop continue when _online_size(u.id) not between 1 and 2; loop exit when _online_size(u.id) >= 3; select t.id into v_t from teams t where t.arena_id = p_arena and t.id <> u.id and _online_size(t.id) between 1 and 2 and _online_size(t.id) <= 4 - _online_size(u.id) order by _online_size(t.id) desc, t.created_at limit 1; exit when v_t is null; for x in select id from players where team_id = v_t and active loop perform _online_move(x.id, u.id); v_moved := v_moved + 1; end loop; end loop; end loop; for u in select t.id from teams t where t.arena_id = p_arena and _online_size(t.id) between 1 and 2 loop for x in select id from players where team_id = u.id and active loop select t.id into v_t from teams t where t.arena_id = p_arena and t.id <> u.id and _online_size(t.id) = 3 order by t.open_squad desc, t.created_at limit 1; exit when v_t is null; perform _online_move(x.id, v_t); v_moved := v_moved + 1; end loop; end loop; for u in select t.id from teams t where t.arena_id = p_arena and _online_size(t.id) between 1 and 2 loop v_need := 3 - _online_size(u.id); for v in select t.id from teams t where t.arena_id = p_arena and t.id <> u.id and _online_size(t.id) = 4 order by t.open_squad desc, t.created_at limit v_need loop select id into v_t from players where team_id = v.id and active order by joined_at desc limit 1; perform _online_move(v_t, u.id); v_moved := v_moved + 1; end loop; if _online_size(u.id) < 3 then v_left := v_left + _online_size(u.id); end if; end loop; update teams set roster_locked = true where arena_id = p_arena and ready; return jsonb_build_object('moved', v_moved, 'left_out', v_left); end $$;
drop function if exists _host_exec_v8(uuid, uuid, text, jsonb, text);
alter function _host_exec(uuid, uuid, text, jsonb, text) rename to _host_exec_v8;
create function _host_exec(p_ev uuid, p_arena uuid, p_cmd text, p_args jsonb, p_reason text) returns jsonb language plpgsql as $$ declare v_seal jsonb; begin if p_cmd = 'drive' and p_arena is not null and _cfg(p_ev, 'online') = 1 then v_seal := _online_seal(p_arena); if (v_seal ->> 'moved')::int > 0 then perform _feed(p_arena, 'online.sealed', v_seal); end if; end if; return _host_exec_v8(p_ev, p_arena, p_cmd, p_args, p_reason); end $$;
drop function if exists _auto_roles_v8(uuid);
alter function _auto_roles(uuid) rename to _auto_roles_v8;
create function _auto_roles(p_arena uuid) returns boolean language plpgsql as $$ declare v_any boolean; t record; r text; v_p uuid; begin v_any := _auto_roles_v8(p_arena); for t in select tm.id from teams tm where tm.arena_id = p_arena and tm.ready and (select count(*) from players q where q.team_id = tm.id and q.active and q.role is not null) = 3 and (select count(*) from players q where q.team_id = tm.id and q.active) = 3 loop select x into r from unnest(array['captain', 'scout', 'decoder', 'intel']) x where not exists (select 1 from players q where q.team_id = t.id and q.active and (q.role = x or q.role2 = x)) limit 1; continue when r is null; select id into v_p from players where team_id = t.id and active and role2 is null order by (role = 'captain'), random() limit 1; update players set role2 = r where id = v_p; insert into squad_chat(team_id, name, kind, body) select t.id, 'Hexa Air', 'system', display_name || ' also covers the ' || r || ' role (squad of 3)' from players where id = v_p; perform _ping_team(t.id, 'roles'); v_any := true; end loop; return v_any; end $$;
create or replace function squad_chat_send(p_token text, p_body text, p_kind text default 'msg') returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; v_body text := trim(coalesce(p_body, '')); v_id bigint; begin p := _auth_player(p_token); if coalesce(p_kind, 'msg') not in ('msg', 'ping') then raise exception 'BAD_KIND'; end if; if char_length(v_body) < 1 or char_length(v_body) > 240 then raise exception 'BAD_MESSAGE'; end if; if (select count(*) from squad_chat where player_id = p.id and at > now() - interval '10 seconds') >= 6 then raise exception 'SLOW_DOWN'; end if; insert into squad_chat(team_id, player_id, name, kind, body) values (p.team_id, p.id, p.display_name, coalesce(p_kind, 'msg'), v_body) returning id into v_id; perform _ping_team(p.team_id, 'chat'); return jsonb_build_object('id', v_id); end $$;
create or replace function squad_chat(p_token text, p_after bigint default 0) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; begin p := _auth_player(p_token); return (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'kind', c.kind, 'body', c.body, 'at', c.at, 'me', c.player_id = p.id) order by c.id), '[]'::jsonb) from (select * from squad_chat where team_id = p.team_id and id > coalesce(p_after, 0) order by id desc limit 60) c); end $$;
drop function if exists _player_state_v8(text);
alter function player_state(text) rename to _player_state_v8;
create function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; p players; t teams; v_clues jsonb; v_id uuid; begin v := _player_state_v8(p_token); p := _auth_player(p_token); if _cfg((select event_id from teams where id = p.team_id), 'online') <> 1 and p.role2 is null then return v; end if; select * into t from teams where id = p.team_id; if p.role2 is not null then v := jsonb_set(v, '{me}', (v -> 'me') || jsonb_build_object('role2', p.role2)); for v_id in select (v -> k ->> 'id')::uuid from unnest(array['mission', 'battle']) k where jsonb_typeof(v -> k) = 'object' and (v -> k ->> 'id') is not null loop select mt.clues into v_clues from mission_instances mi join mission_templates mt on mt.id = mi.template_id where mi.id = v_id; if v_clues ? p.role2 then if v -> 'mission' ->> 'id' = v_id::text then v := jsonb_set(v, '{mission,clue2}', v_clues -> p.role2); else v := jsonb_set(v, '{battle,clue2}', v_clues -> p.role2); end if; end if; end loop; end if; if _cfg(t.event_id, 'online') = 1 then v := v || jsonb_build_object('online', jsonb_build_object( 'code', t.squad_code, 'open', t.open_squad, 'size', _online_size(t.id), 'squad', (select coalesce(jsonb_agg(jsonb_build_object('name', q.display_name, 'email', m.email, 'me', q.id = p.id, 'online', q.last_seen_at > now() - interval '30 seconds', 'role', q.role, 'role2', q.role2) order by q.joined_at), '[]'::jsonb) from players q left join online_members m on m.player_id = q.id where q.team_id = t.id and q.active), 'chat_last', (select max(id) from squad_chat where team_id = t.id))); end if; return v; end $$;
create or replace function host_attendance(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); insert into audit_log(event_id, actor, action) values (v_ev, 'host', 'attendance_export'); return (select coalesce(jsonb_agg(jsonb_build_object( 'emp_id', m.emp_id, 'email', m.email, 'name', m.name, 'squad', t.number, 'squad_name', t.name, 'squad_code', t.squad_code, 'map', a.number, 'size', (select count(*) from players q where q.team_id = t.id and q.active), 'role', p.role, 'joined_at', m.first_joined_at, 'last_seen_at', p.last_seen_at, 'points', t.points) order by a.number, t.number, m.name), '[]'::jsonb) from online_members m left join players p on p.id = m.player_id left join teams t on t.id = p.team_id left join arenas a on a.id = t.arena_id where m.event_id = v_ev); end $$;
create or replace function host_online_summary(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); return jsonb_build_object( 'players', (select count(*) from online_members where event_id = v_ev), 'max_maps', _cfg(v_ev, 'online_max_maps'), 'maps', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'number', a.number, 'phase', a.phase, 'squads', (select count(*) from teams t where t.arena_id = a.id), 'ready', (select count(*) from teams t where t.arena_id = a.id and t.ready), 'full', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) = 4), 'short', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) between 1 and 2), 'players', (select count(*) from players q join teams t on t.id = q.team_id where t.arena_id = a.id and q.active)) order by a.number), '[]'::jsonb) from arenas a where a.event_id = v_ev)); end $$;
do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;

-- ═══ 0910_squad_watch.sql ═══
alter table players add column if not exists away boolean not null default false;
alter table players add column if not exists away_at timestamptz;
alter table players add column if not exists orig_role text;
alter table players add column if not exists role2_bot boolean not null default false;
alter table arenas add column if not exists watch_at timestamptz;
create table if not exists squad_chat ( id bigserial primary key, team_id uuid not null references teams(id) on delete cascade, player_id uuid references players(id) on delete set null, name text not null, kind text not null default 'msg' check (kind in ('msg', 'ping', 'system')), body text not null check (char_length(body) between 1 and 240), at timestamptz not null default now() );
drop function if exists _defaults_v8();
alter function _defaults() rename to _defaults_v8;
create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v8() || jsonb_build_object( 'away_seconds', 60) $$;
create or replace function _sq_note(p_team uuid, p_body text) returns void language sql as $$ insert into squad_chat(team_id, name, kind, body) values (p_team, 'Hexa Air', 'system', left(p_body, 240)); select _ping_team(p_team, 'chat'); $$;
create or replace function _sq_cover(p_team uuid, p_role text, p_gone uuid) returns uuid language plpgsql as $$ declare v_holder uuid; v_name text; v_gone text; begin if p_role is null or p_role = 'captain' then return null; end if; if exists (select 1 from players where team_id = p_team and active and not away and (role = p_role or role2 = p_role)) then return null; end if; select id, display_name into v_holder, v_name from players where team_id = p_team and active and not away and id <> p_gone and role is not null and role2 is null order by (role = 'captain'), joined_at limit 1; select display_name into v_gone from players where id = p_gone; if v_holder is null then perform _sq_note(p_team, '🤖 ' || coalesce(v_gone, 'A teammate') || ' is offline — nobody is free to read the ' || p_role || ' clue'); return null; end if; update players set role2 = p_role, role2_bot = true where id = v_holder; perform _sq_note(p_team, '🤖 Bot joined for ' || coalesce(v_gone, 'a teammate') || ' — ' || v_name || ' now also sees the ' || p_role || ' clue'); return v_holder; end $$;
create or replace function _squad_gone(p_player uuid) returns void language plpgsql as $$ declare p players; q players; r text; v_r2 text; begin select * into p from players where id = p_player; update players set away = true, away_at = now() where id = p_player; perform _sq_note(p.team_id, '📶 ' || p.display_name || ' disconnected'); if p.role = 'captain' then select * into q from players where team_id = p.team_id and active and not away and id <> p.id and role is not null order by (role2 is not null), joined_at limit 1; if q.id is not null then r := q.role; update players set role = null where id in (p.id, q.id); update players set role = 'captain', orig_role = coalesce(orig_role, r) where id = q.id; update players set role = r, orig_role = 'captain' where id = p.id; perform _sq_note(p.team_id, '⭐ ' || q.display_name || ' is captain while ' || p.display_name || ' is away'); p.role := r; select role2 into v_r2 from players where id = q.id; if v_r2 is not null then update players set role2 = null, role2_bot = false where id = q.id; perform _sq_cover(p.team_id, v_r2, p.id); end if; end if; end if; if p.role2 is not null then update players set role2 = null, role2_bot = false where id = p.id; perform _sq_cover(p.team_id, p.role2, p.id); end if; perform _sq_cover(p.team_id, p.role, p.id); perform _ping_team(p.team_id, 'roles'); end $$;
create or replace function _squad_back(p_player uuid) returns void language plpgsql as $$ declare p players; q players; r text; begin select * into p from players where id = p_player; update players set away = false, away_at = null where id = p_player; update players set role2 = null, role2_bot = false where team_id = p.team_id and role2_bot and role2 = p.role; if p.orig_role = 'captain' then select * into q from players where team_id = p.team_id and active and role = 'captain' and id <> p.id; if q.id is not null and q.orig_role is not null then r := q.orig_role; update players set role = null where id in (p.id, q.id); update players set role = 'captain', orig_role = null where id = p.id; update players set role = r, orig_role = null where id = q.id; update players set role2 = null, role2_bot = false where team_id = p.team_id and role2_bot and role2 = r; perform _sq_note(p.team_id, '⭐ ' || p.display_name || ' is back as captain'); else update players set orig_role = null where id = p.id; end if; end if; perform _sq_note(p.team_id, '✅ ' || p.display_name || ' reconnected' || case when p.role is not null then ' — the bot left' else '' end); perform _ping_team(p.team_id, 'roles'); end $$;
create or replace function _squad_watch(p_arena uuid) returns boolean language plpgsql as $$ declare t record; p record; v_any boolean := false; v_away int; begin update arenas set watch_at = now() where id = p_arena and phase in ('shuttle', 'roles', 'play', 'finale') and (watch_at is null or watch_at < now() - interval '4 seconds'); if not found then return false; end if; v_away := _cfg((select event_id from arenas where id = p_arena), 'away_seconds'); for t in select tm.id from teams tm where tm.arena_id = p_arena and tm.ready and not exists (select 1 from bots b where b.team_id = tm.id) loop for p in select id from players where team_id = t.id and active and away and last_seen_at > now() - interval '20 seconds' loop perform _squad_back(p.id); v_any := true; end loop; for p in select id from players where team_id = t.id and active and not away and last_seen_at < now() - make_interval(secs => v_away) loop perform _squad_gone(p.id); v_any := true; end loop; end loop; return v_any; end $$;
drop function if exists _tick_v9(uuid, boolean);
alter function _tick(uuid, boolean) rename to _tick_v9;
create function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare v boolean; begin if not p_force and exists (select 1 from arenas where id = p_arena and last_tick_at > now() - interval '800 milliseconds') then return false; end if; if not pg_try_advisory_xact_lock(hashtext('tick-gate' || p_arena::text)) then return false; end if; v := _tick_v9(p_arena, p_force); if _squad_watch(p_arena) then v := true; end if; return v; end $$;
drop function if exists _player_state_v9(text);
alter function player_state(text) rename to _player_state_v9;
create function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; p players; ph text; begin v := _player_state_v9(p_token); p := _auth_player(p_token); ph := v -> 'arena' ->> 'phase'; v := v || jsonb_build_object('squad', (select coalesce(jsonb_agg(jsonb_build_object( 'name', q.display_name, 'me', q.id = p.id, 'role', q.role, 'role2', q.role2, 'bot2', q.role2_bot, 'status', case when q.away then 'away' when q.last_seen_at > now() - interval '15 seconds' then 'on' else 'weak' end) order by q.joined_at), '[]'::jsonb) from players q where q.team_id = p.team_id and q.active)); v := jsonb_set(v, '{me}', (v -> 'me') || jsonb_build_object('role2', p.role2, 'role2_bot', p.role2_bot)); v := v || jsonb_build_object('chat_last', (select max(id) from squad_chat where team_id = p.team_id)); if ph not in ('results', 'ended') then v := v - 'leaderboard'; end if; return v; end $$;
drop function if exists _spectator_state_v9(text);
alter function spectator_state(text) rename to _spectator_state_v9;
create function spectator_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; begin v := _spectator_state_v9(p_token); if v -> 'arena' is not null and (v -> 'arena' ->> 'phase') not in ('results', 'ended') then v := v - 'leaderboard'; if jsonb_typeof(v -> 'squads') = 'array' then v := jsonb_set(v, '{squads}', (select coalesce(jsonb_agg(s - 'points' - 'final_points' - 'rank'), '[]'::jsonb) from jsonb_array_elements(v -> 'squads') s)); end if; end if; return v; end $$;
do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;
do $$ declare t text; begin foreach t in array array['squad_chat'] loop execute format('alter table %I enable row level security', t); execute format('revoke all on table %I from anon, authenticated', t); end loop; end $$;

-- ═══ 0920_online_start.sql ═══
drop function if exists _defaults_v9();
alter function _defaults() rename to _defaults_v9;
create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v9() || jsonb_build_object( 'online_started', 0) $$;
create or replace function _online_arena(p_ev uuid) returns uuid language plpgsql as $$ declare v_arena uuid; begin if _cfg(p_ev, 'online_started') = 1 then raise exception 'GAME_STARTED'; end if; select id into v_arena from arenas where event_id = p_ev order by number limit 1; if v_arena is null then insert into arenas(event_id, number, name) values (p_ev, 1, 'Map 1') returning id into v_arena; end if; return v_arena; end $$;
create or replace function _online_open(p_team uuid) returns boolean language sql stable as $$ select exists (select 1 from teams t join arenas a on a.id = t.arena_id where t.id = p_team and (a.phase in ('lobby', 'boarding', 'shuttle', 'roles') or (a.phase = 'play' and not t.dropped and t.jump_at is null))) $$;
create or replace function _online_late_team(p_ev uuid) returns uuid language sql stable as $$ select t.id from teams t join arenas a on a.id = t.arena_id where t.event_id = p_ev and t.ready and _online_open(t.id) and (select count(*) from players q where q.team_id = t.id and q.active) < 4 order by (select count(*) from players q where q.team_id = t.id and q.active) desc, a.number, t.number limit 1 $$;
create or replace function _online_seal_event(p_ev uuid) returns jsonb language plpgsql as $$ declare u record; v record; x record; v_t uuid; v_need int; v_moved int := 0; v_left int := 0; begin for u in select t.id from teams t where t.event_id = p_ev order by _online_size(t.id) desc, t.open_squad, t.created_at loop continue when _online_size(u.id) not between 1 and 2; loop exit when _online_size(u.id) >= 3; select t.id into v_t from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) between 1 and 2 and _online_size(t.id) <= 4 - _online_size(u.id) order by _online_size(t.id) desc, t.created_at limit 1; exit when v_t is null; for x in select id from players where team_id = v_t and active loop perform _online_move(x.id, u.id); v_moved := v_moved + 1; end loop; end loop; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) between 1 and 2 loop for x in select id from players where team_id = u.id and active loop select t.id into v_t from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) = 3 order by t.open_squad desc, t.created_at limit 1; exit when v_t is null; perform _online_move(x.id, v_t); v_moved := v_moved + 1; end loop; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) between 1 and 2 loop v_need := 3 - _online_size(u.id); for v in select t.id from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) = 4 order by t.open_squad desc, t.created_at limit v_need loop select id into v_t from players where team_id = v.id and active order by joined_at desc limit 1; perform _online_move(v_t, u.id); v_moved := v_moved + 1; end loop; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) = 1 loop select t.id into v_t from teams t where t.event_id = p_ev and t.id <> u.id and _online_size(t.id) = 3 order by t.open_squad desc, t.created_at limit 1; if v_t is not null then select id into v_t from players where team_id = v_t and active order by joined_at desc limit 1; perform _online_move(v_t, u.id); v_moved := v_moved + 1; end if; end loop; for u in select t.id from teams t where t.event_id = p_ev and _online_size(t.id) = 1 loop v_left := v_left + 1; end loop; update teams t set ready = (select count(*) from players q where q.team_id = t.id and q.active) >= 2, roster_locked = (select count(*) from players q where q.team_id = t.id and q.active) >= 4 where t.event_id = p_ev; return jsonb_build_object('moved', v_moved, 'left_out', v_left); end $$;
create or replace function _online_seal(p_arena uuid) returns jsonb language plpgsql as $$ declare v jsonb; begin v := jsonb_build_object('moved', 0, 'left_out', 0); update teams t set ready = true where t.arena_id = p_arena and (select count(*) from players q where q.team_id = t.id and q.active) >= 2; return v; end $$;
create or replace function _auto_roles(p_arena uuid) returns boolean language plpgsql as $$ declare v_any boolean; t record; r text; v_p uuid; begin v_any := _auto_roles_v8(p_arena); for t in select tm.id from teams tm where tm.arena_id = p_arena and tm.ready and not exists (select 1 from players q where q.team_id = tm.id and q.active and q.role is null) and (select count(*) from players q where q.team_id = tm.id and q.active and not q.away) between 1 and 3 loop for r in select x from unnest(array['scout', 'decoder', 'intel', 'captain']) x where not exists (select 1 from players q where q.team_id = t.id and q.active and (q.role = x or q.role2 = x)) loop continue when r = 'captain'; select id into v_p from players where team_id = t.id and active and not away and role2 is null order by (role = 'captain'), random() limit 1; exit when v_p is null; update players set role2 = r, role2_bot = (select count(*) from players q where q.team_id = t.id and q.active) < 3 where id = v_p; insert into squad_chat(team_id, name, kind, body) select t.id, 'Hexa Air', 'system', display_name || ' also covers the ' || r || ' role' from players where id = v_p; perform _ping_team(t.id, 'roles'); v_any := true; end loop; end loop; return v_any; end $$;
create or replace function host_online_start(p_token text, p_length text default 'standard') returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_seal jsonb; v_squads int; v_maps int; v_size int; v_max int; i int; v_arena uuid; t record; k int := 0; v_ids uuid[]; v_res jsonb := '[]'::jsonb; a record; v_bus int; begin v_ev := _auth_host(p_token); if _cfg(v_ev, 'online') <> 1 then raise exception 'NOT_ONLINE_EVENT'; end if; if _cfg(v_ev, 'online_started') = 1 then raise exception 'ALREADY_STARTED'; end if; if coalesce(p_length, 'standard') not in ('quick', 'standard', 'full') then raise exception 'BAD_LENGTH'; end if; perform pg_advisory_xact_lock(hashtext('online:' || v_ev::text)); v_seal := _online_seal_event(v_ev); delete from teams tm where tm.event_id = v_ev and not exists (select 1 from players q where q.team_id = tm.id and q.active); select count(*) into v_squads from teams where event_id = v_ev and ready; if v_squads = 0 then raise exception 'NO_READY_SQUADS'; end if; v_size := least(15, greatest(1, _cfg(v_ev, 'arena_size'))); v_max := _cfg(v_ev, 'online_max_maps'); v_maps := least(greatest(1, ceil(v_squads::numeric / v_size)::int), v_max); if v_squads > v_maps * v_size then raise exception 'TOO_MANY_SQUADS: % squads need more than % maps — raise "Most maps"', v_squads, v_max; end if; for i in 1..v_maps loop if not exists (select 1 from arenas where event_id = v_ev and number = i) then insert into arenas(event_id, number, name) values (v_ev, i, 'Map ' || i); end if; end loop; select array_agg(id order by number) into v_ids from arenas where event_id = v_ev and number <= v_maps; for t in select id from teams where event_id = v_ev and ready order by random() loop update teams set arena_id = v_ids[1 + (k % v_maps)] where id = t.id; k := k + 1; end loop; update teams set arena_id = v_ids[1] where event_id = v_ev and not ready; for a in select id from arenas where event_id = v_ev and number <= v_maps loop v_bus := 0; for t in select id from teams where arena_id = a.id order by number loop update teams set bus = 1 + v_bus / greatest(1, _cfg(v_ev, 'bus_size')) where id = t.id; v_bus := v_bus + 1; end loop; end loop; update events set settings = settings || '{"online_started": 1}'::jsonb where id = v_ev; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'online_start', jsonb_build_object('squads', v_squads, 'maps', v_maps, 'length', p_length) || v_seal); for i in 1..v_maps loop v_res := v_res || jsonb_build_object('map', i, 'start', host_command(p_token, v_ids[i], 'start_match', jsonb_build_object('length', coalesce(p_length, 'standard')), 'online start')); end loop; return jsonb_build_object('squads', v_squads, 'maps', v_maps, 'merged', v_seal -> 'moved', 'left_out', v_seal -> 'left_out', 'started', v_res); end $$;
drop function if exists _player_state_v10(text);
alter function player_state(text) rename to _player_state_v10;
create function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v jsonb; begin v := _player_state_v10(p_token); if jsonb_typeof(v -> 'online') = 'object' then v := jsonb_set(v, '{online,started}', to_jsonb(_cfg((select event_id from players p join teams t on t.id = p.team_id where p.session_hash = _hash(p_token)), 'online_started') = 1)); end if; return v; end $$;
create or replace function host_online_summary(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_sq int; v_size int; begin v_ev := _auth_host(p_token); select count(*) into v_sq from teams t where t.event_id = v_ev and exists (select 1 from players q where q.team_id = t.id and q.active); v_size := least(15, greatest(1, _cfg(v_ev, 'arena_size'))); return jsonb_build_object( 'players', (select count(*) from online_members where event_id = v_ev), 'started', _cfg(v_ev, 'online_started') = 1, 'max_maps', _cfg(v_ev, 'online_max_maps'), 'squads', v_sq, 'full', (select count(*) from teams t where t.event_id = v_ev and (select count(*) from players q where q.team_id = t.id and q.active) = 4), 'three', (select count(*) from teams t where t.event_id = v_ev and (select count(*) from players q where q.team_id = t.id and q.active) = 3), 'short', (select count(*) from teams t where t.event_id = v_ev and (select count(*) from players q where q.team_id = t.id and q.active) between 1 and 2), 'maps_needed', greatest(1, ceil(greatest(v_sq, 1)::numeric / v_size)::int), 'maps', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'number', a.number, 'phase', a.phase, 'squads', (select count(*) from teams t where t.arena_id = a.id), 'ready', (select count(*) from teams t where t.arena_id = a.id and t.ready), 'full', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) = 4), 'short', (select count(*) from teams t where t.arena_id = a.id and (select count(*) from players q where q.team_id = t.id and q.active) between 1 and 2), 'players', (select count(*) from players q join teams t on t.id = q.team_id where t.arena_id = a.id and q.active)) order by a.number), '[]'::jsonb) from arenas a where a.event_id = v_ev)); end $$;
do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary', 'host_online_start']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;

-- ═══ 0930_perf.sql ═══
create table if not exists arena_pings ( arena_id uuid not null, kind text not null, at timestamptz not null default now(), primary key (arena_id, kind) );
alter table arena_pings enable row level security;
revoke all on table arena_pings from anon, authenticated;
create or replace function _ping_arena(p_arena uuid, p_kind text default 'state') returns void language plpgsql as $$ declare v_gap interval; v_key text; begin if p_kind not in ('phase', 'finale', 'results', 'paused') then v_gap := case when p_kind = 'tick' then interval '5 seconds' else interval '2 seconds' end; v_key := case when p_kind = 'tick' then 'tick' else 'any' end; if not pg_try_advisory_xact_lock(hashtext('ping-' || v_key || p_arena::text)) then return; end if; if exists (select 1 from arena_pings where arena_id = p_arena and kind = v_key and at > now() - v_gap) then return; end if; insert into arena_pings(arena_id, kind, at) values (p_arena, v_key, now()) on conflict (arena_id, kind) do update set at = excluded.at; end if; perform _ping('arena-' || p_arena::text, p_kind); end $$;

-- ═══ 0940_cron_clock.sql ═══
do $$ begin create extension if not exists pg_cron with schema pg_catalog; exception when others then raise notice 'pg_cron is not available here — phones keep running the clock (fine for tests)'; end $$;
create table if not exists tick_heartbeat (id int primary key default 1, at timestamptz not null default now());
alter table tick_heartbeat enable row level security;
revoke all on table tick_heartbeat from anon, authenticated;
create or replace function _tick_safe(p_arena uuid) returns void language plpgsql as $$ begin perform set_config('hexa.cron', '1', true); perform _tick(p_arena); exception when others then raise warning 'tick % failed: %', p_arena, sqlerrm; end $$;
create or replace procedure hexa_tick_all() language plpgsql as $$ declare r record; v_ids uuid[]; begin insert into tick_heartbeat(id, at) values (1, now()) on conflict (id) do update set at = excluded.at; commit; select array_agg(a.id) into v_ids from arenas a where a.phase <> 'ended' and (a.autopilot or a.phase <> 'lobby') and (a.last_tick_at is null or a.last_tick_at > now() - interval '10 minutes' or exists (select 1 from teams t join players p on p.team_id = t.id where t.arena_id = a.id and p.last_seen_at > now() - interval '10 minutes')); if v_ids is null then return; end if; for i in 1 .. array_length(v_ids, 1) loop perform _tick_safe(v_ids[i]); commit; end loop; end $$;
create or replace function _cron_alive() returns boolean language sql stable as $$ select exists (select 1 from tick_heartbeat where id = 1 and at > now() - interval '3 seconds') $$;
do $$ declare d text; n text; begin d := pg_get_functiondef('_tick(uuid, boolean)'::regprocedure); if position('_cron_alive()' in d) > 0 then return; end if; n := regexp_replace(d, 'begin\s+if not p_force and exists \(select 1 from arenas where id = p_arena and last_tick_at', 'begin
  if not p_force and current_setting(''hexa.cron'', true) is distinct from ''1'' and _cron_alive() then return false; end if;
  if not p_force and exists (select 1 from arenas where id = p_arena and last_tick_at'); if n = d then raise exception 'v12: could not patch _tick'; end if; execute n; end $$;
do $$ begin if exists (select 1 from pg_extension where extname = 'pg_cron') then perform cron.unschedule(jobid) from cron.job where jobname = 'hexa-tick'; perform cron.schedule('hexa-tick', '1 seconds', 'call hexa_tick_all()'); raise notice 'Game clock scheduled: hexa-tick every second'; end if; exception when others then raise notice 'could not schedule the game clock (%); phones keep running it', sqlerrm; end $$;
